    INSERT INTO units (level_id, title, description, unit_type, order_index) VALUES (v_level_id, 'Hingga Mencapai Titik Kritis (～に至って)', 'Kuasai ungkapan titik balik, eskalasi krisis, dan analisis sejarah formal dalam wacana bisnis serta berita tingkat JLPT N1.', 'curriculum', 1) RETURNING id INTO v_unit_id;
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kosakata Krisis & Eskalasi', 'Kosakata Krisis', 'n1-u1-kosakata', 'book-open', 15, 1) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk melengkapi kalimat berita berikut: 経済状況の___により、政府は緊急対策を講じた。', '{"options":["自動化","簡略化","活性化","深刻化"],"translation":"Akibat memburuknya kondisi ekonomi secara serius, pemerintah mengambil langkah darurat.","sentence_template":"経済状況の[blank]により、政府は緊急対策を講じた。"}'::jsonb, '{"selected":"深刻化"}'::jsonb, '深刻化 (shinkokuka) berarti ''menjadi semakin serius/kritis'', sangat lazim dalam konteks krisis ekonomi atau sosial di level N1.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan istilah manajemen krisis yang tepat: 不正会計が___し、経営陣の責任が厳しく問われている。', '{"options":["出発","発揮","発行","発覚"],"translation":"Kecurangan akuntansi terbongkar, dan tanggung jawab jajaran direksi dipertanyakan secara keras.","sentence_template":"不正会計が[blank]し、経営陣の責任が厳しく問われている。"}'::jsonb, '{"selected":"発覚"}'::jsonb, '発覚 (hakkaku) berarti terbongkarnya suatu skandal, pelanggaran, atau fakta tersembunyi.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata formal yang tepat: 表面的な修正ではなく、___な改革が求められている。', '{"options":["一時的","抜本的","偶発的","消極的"],"translation":"Bukan perbaikan di permukaan saja, melainkan reformasi yang mendasar yang dibutuhkan.","sentence_template":"表面的な修正ではなく、[blank]な改革が求められている。"}'::jsonb, '{"selected":"抜本的"}'::jsonb, '抜本的 (bapponteki) berarti ''mendasar/radikal hingga ke akar masalah'', kontras dengan 表面的な (di permukaan).', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan laporan singkat berikut. Langkah apa yang diambil perusahaan setelah insiden terjadi?', '{"audio_text":"大規模な情報漏洩が発生したことを受け、本社に緊急対策本部が設置されました。","options":[{"id":"opt_1","text":"Membentuk markas besar penanggulangan darurat di kantor pusat"},{"id":"opt_2","text":"Memindahkan kantor pusat ke gedung baru"},{"id":"opt_3","text":"Menunda peluncuran produk selama satu tahun"},{"id":"opt_4","text":"Menghapus seluruh data pelanggan lama"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '緊急対策本部が設置されました berarti ''markas besar penanggulangan darurat telah dibentuk'' akibat kebocoran informasi (情報漏洩).', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan berikut. Apa yang sedang dihadapi oleh proyek tersebut?', '{"audio_text":"長引く資金不足により、開発計画は事実上の破綻状態に陥っている。","options":[{"id":"opt_1","text":"Berhasil memperoleh pendanaan tambahan dari investor"},{"id":"opt_2","text":"Secara de facto jatuh dalam kondisi gagal total akibat kekurangan dana berkepanjangan"},{"id":"opt_3","text":"Sedang memasuki tahap uji coba akhir dengan hasil memuaskan"},{"id":"opt_4","text":"Dialihkan pengelolaannya ke anak perusahaan di luar negeri"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '事実上の破綻状態に陥っている berarti ''secara de facto terperosok ke dalam kondisi bangkrut/gagal total''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kita harus segera menyusun langkah pencegahan terulangnya kejadian."', '{"display_text":"早急に再発防止策を策定しなければならない。","romaji":"Soukyuu ni saihatsu boushisaku wo sakutei shinakereba naranai.","phonetic_breakdown":["sou-kyuu","ni","sai-ha-tsu","bou-shi-sa-ku","wo","sa-ku-tei","shi-na-ke-re-ba","na-ra-nai"]}'::jsonb, '{"expected_transcript":"早急に再発防止策を策定しなければならない。"}'::jsonb, '再発防止策 (saihatsu boushisaku) adalah istilah standar bisnis/pemerintahan untuk ''langkah pencegahan terulangnya insiden''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Pola ～に至って & Variannya', 'Pola ～に至って', 'n1-u1-pola-utama', 'sparkle', 20, 2) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan pola tata bahasa N1 yang tepat: 事態がここまで悪化する___、ようやく経営陣は重い腰を上げた。', '{"options":["に先立って","に至って","に沿って","をめぐって"],"translation":"Setelah situasi memburuk sampai sejauh ini, barulah jajaran direksi akhirnya bergerak.","sentence_template":"事態がここまで悪化する[blank]、ようやく経営陣は重い腰を上げた。"}'::jsonb, '{"selected":"に至って"}'::jsonb, '～に至って menyatakan bahwa setelah mencapai titik ekstrem/kritis tertentu, barulah suatu reaksi atau kenyataan muncul.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk menyatakan kondisi yang sudah terlambat: 今___、後悔しても手遅れだ。', '{"options":["に応じて","に際して","に至るまで","に至っては"],"translation":"Kalau sudah sampai saat sekarang ini, menyesal pun sudah terlambat.","sentence_template":"今[blank]、後悔しても手遅れだ。"}'::jsonb, '{"selected":"に至っては"}'::jsonb, '今に至っては (sudah sampai titik sekarang ini) sering diikuti ungkapan bahwa situasinya tidak dapat diubah lagi.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut untuk menunjukkan cakupan menyeluruh: 社長から新入社員___、全員が研修に参加した。', '{"options":["に至るまで","を契機に","を踏まえて","に至っては"],"translation":"Mulai dari direktur utama hingga karyawan baru, semuanya mengikuti pelatihan.","sentence_template":"社長から新入社員[blank]、全員が研修に参加した。"}'::jsonb, '{"selected":"に至るまで"}'::jsonb, 'AからBに至るまで menunjukkan rentang ekstrem dari A sampai ke detail atau tingkat B.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setelah mencapai tahap ini, tidak ada jalan lain selain mundur."', '{"tokens":["に応じて","この","撤退","する","ながら","に至っては","段階","ほかない"],"target_translation":"Setelah mencapai tahap ini, tidak ada jalan lain selain mundur.","romaji":"Kono dankai ni itatte wa tettai suru hoka nai."}'::jsonb, '["この","段階","に至っては","撤退","する","ほかない"]'::jsonb, 'この段階に至っては (kalau sudah sampai tahap ini) berpasangan alami dengan ～するほかない (tidak ada pilihan lain selain...).', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dia menjelaskan kronologi hingga tercapainya keputusan itu."', '{"tokens":["をめぐった","を","丁寧に","ばかりに","説明した","に至った","決定","経緯"],"target_translation":"Dia menjelaskan kronologi hingga tercapainya keputusan itu.","romaji":"Kettei ni itatta keii wo teinei ni setsumei shita."}'::jsonb, '["決定","に至った","経緯","を","丁寧に","説明した"]'::jsonb, '決定に至った経緯 berarti ''latar belakang/kronologi yang mengarah pada keputusan tersebut''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Baru setelah jatuh sakit parah, saya menyadari pentingnya kesehatan."', '{"display_text":"大病を患うに至って、初めて健康のありがたみを知った。","romaji":"Taibyou wo wazurau ni itatte, hajimete kenkou no arigatami wo shitta.","phonetic_breakdown":["tai-byou","wo","wa-zu-rau","ni","i-ta-tte","ha-ji-me-te","ken-kou","no","a-ri-ga-ta-mi","wo","shi-tta"]}'::jsonb, '{"expected_transcript":"大病を患うに至って、初めて健康のありがたみを知った。"}'::jsonb, 'Pola ～に至って、初めて～ menegaskan kesadaran yang baru muncul setelah mencapai titik ekstrem.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Wacana Krisis & Titik Balik', 'Dengar & Baca U1', 'n1-u1-dengar-baca', 'play-circle', 20, 3) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan kutipan editorial berikut. Mengapa publik baru bereaksi keras sekarang?', '{"audio_text":"度重なる警告が無視され続け、大規模な事故が発生するに至って、ようやく安全基準の見直しが始まった。","options":[{"id":"opt_1","text":"Karena standar keamanan sebelumnya sudah terlalu ketat"},{"id":"opt_2","text":"Karena peringatan berkali-kali sudah langsung ditindaklanjuti sejak awal"},{"id":"opt_3","text":"Karena peninjauan standar baru dimulai setelah kecelakaan besar benar-benar terjadi"},{"id":"opt_4","text":"Karena biaya pemeliharaan fasilitas meningkat drastis"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '大規模な事故が発生するに至って、ようやく... menunjukkan kritik bahwa tindakan baru diambil setelah insiden besar terjadi.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan laporan rapat direksi berikut. Apa kesimpulan mengenai proses negosiasi?', '{"audio_text":"半年以上にわたる協議の末、両社は合意に至らず、提携交渉は白紙に戻された。","options":[{"id":"opt_1","text":"Kedua perusahaan sepakat menandatangani kontrak jangka panjang"},{"id":"opt_2","text":"Negosiasi diperpanjang selama enam bulan lagi"},{"id":"opt_3","text":"Salah satu perusahaan mengakuisisi seluruh saham mitra"},{"id":"opt_4","text":"Tidak tercapai kesepakatan sehingga perundingan kembali ke titik nol"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '合意に至らず (tidak mencapai kesepakatan) dan 白紙に戻された (dikembalikan ke kertas kosong/titik nol).', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan sejarah perusahaan berikut. Apa yang dicakup dalam reformasi tersebut?', '{"audio_text":"創業以来の危機に直面し、業務フローから人事評価制度に至るまで全面的な刷新が行われた。","options":[{"id":"opt_1","text":"Pembaruan menyeluruh dari alur kerja hingga sistem evaluasi SDM"},{"id":"opt_2","text":"Hanya perubahan nama merek dan logo perusahaan"},{"id":"opt_3","text":"Penutupan seluruh cabang di luar negeri saja"},{"id":"opt_4","text":"Pengurangan jam kerja karyawan tanpa mengubah sistem evaluasi"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '業務フローから人事評価制度に至るまで berarti ''mulai dari alur kerja hingga sistem penilaian SDM''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi teks berita berikut: 交渉が決裂___、労使双方は法的措置を検討し始めた。', '{"options":["するに先立ち","するに至り","するに際し","するに連れ"],"translation":"Setelah perundingan mencapai kebuntuan total, pihak serikat pekerja dan manajemen mulai mempertimbangkan jalur hukum.","sentence_template":"交渉が決裂[blank]、労使双方は法的措置を検討し始めた。"}'::jsonb, '{"selected":"するに至り"}'::jsonb, 'するに至り adalah bentuk bahasa tulis (ren''youkei) dari するに至って yang sangat sering muncul dalam berita formal.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih ungkapan yang tepat: 細かい配線の配置___、設計図には一切の妥協が見られない。', '{"options":["をよそに","に至っては","に至るまで","を皮切りに"],"translation":"Hingga detail penempatan kabel yang sangat halus sekalipun, tidak tampak sedikit pun kompromi pada cetak birunya.","sentence_template":"細かい配線の配置[blank]、設計図には一切の妥協が見られない。"}'::jsonb, '{"selected":"に至るまで"}'::jsonb, '～に至るまで menekankan ketelitian sampai ke bagian paling kecil sekalipun.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluatif berikut: 信頼関係が完全に失われた___、共同研究の継続は困難である。', '{"options":["今に先立って","今をめぐって","今に至っては","今に沿って"],"translation":"Kini setelah hubungan saling percaya hilang sepenuhnya, kelanjutan riset bersama menjadi sulit.","sentence_template":"信頼関係が完全に失われた[blank]、共同研究の継続は困難である。"}'::jsonb, '{"selected":"今に至っては"}'::jsonb, '～た今に至っては menegaskan bahwa kondisi saat ini sudah mencapai titik yang menyulitkan kelanjutan.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Bicara & Rakit Analisis Krisis', 'Bicara & Rakit U1', 'n1-u1-bicara-rakit', 'microphone', 20, 4) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Baru setelah situasi memburuk, mereka mulai bertindak."', '{"display_text":"事態が深刻化するに至って、初めて対応に乗り出した。","romaji":"Jitai ga shinkokuka suru ni itatte, hajimete taiou ni noridashita.","phonetic_breakdown":["ji-tai","ga","shin-ko-ku-ka","su-ru","ni","i-ta-tte","ha-ji-me-te","tai-ou","ni","no-ri-da-shi-ta"]}'::jsonb, '{"expected_transcript":"事態が深刻化するに至って、初めて対応に乗り出した。"}'::jsonb, '対応に乗り出す berarti ''mulai turun tangan menangani'', sering dipadukan dengan ～に至って.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mulai dari perencanaan hingga pelaksanaan, dia mengawasi semuanya."', '{"display_text":"企画の立案から現場の運用に至るまで、彼が統括した。","romaji":"Kikaku no ritsuan kara genba no un''you ni itaru made, kare ga toukatsu shita.","phonetic_breakdown":["ki-ka-ku","no","ri-tsu-an","ka-ra","gen-ba","no","un-you","ni","i-ta-ru","ma-de","ka-re","ga","tou-ka-tsu","shi-ta"]}'::jsonb, '{"expected_transcript":"企画の立案から現場の運用に至るまで、彼が統括した。"}'::jsonb, '立案 (ritsuan: penyusunan rencana) hingga 運用 (un''you: operasional lapangan) dirangkai dengan ～に至るまで.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bagaimana masalah ini sampai berkembang sejauh ini?"', '{"display_text":"なぜ問題がここまで拡大するに至ったのか、検証が必要だ。","romaji":"Naze mondai ga koko made kakudai suru ni itatta no ka, kenshou ga hitsuyou da.","phonetic_breakdown":["na-ze","mon-dai","ga","ko-ko","ma-de","ka-ku-dai","su-ru","ni","i-ta-tta","no","ka","ken-shou","ga","hi-tsu-you","da"]}'::jsonb, '{"expected_transcript":"なぜ問題がここまで拡大するに至ったのか、検証が必要だ。"}'::jsonb, '拡大するに至ったのか menanyakan proses/sebab hingga masalah meluas sampai titik tersebut.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Baru setelah kehilangan kepercayaan publik, dia mengundurkan diri."', '{"tokens":["ばかりに","ようやく","世論の","信頼を","に至って","失う","辞任した","に沿って"],"target_translation":"Baru setelah kehilangan kepercayaan publik, dia mengundurkan diri.","romaji":"Seron no shinrai wo ushinau ni itatte youyaku jinin shita."}'::jsonb, '["世論の","信頼を","失う","に至って","ようやく","辞任した"]'::jsonb, '世論の信頼を失うに至って (hingga kehilangan kepercayaan publik) diikuti ようやく辞任した (akhirnya mengundurkan diri).', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sekarang sudah terlambat untuk menyalahkan siapa pun."', '{"tokens":["仕方が","責めても","に至るまで","どころか","ない","に至っては","今","誰を"],"target_translation":"Sekarang sudah terlambat untuk menyalahkan siapa pun.","romaji":"Ima ni itatte wa dare wo semete mo shikata ga nai."}'::jsonb, '["今","に至っては","誰を","責めても","仕方が","ない"]'::jsonb, '今に至っては menegaskan situasi sudah terlanjur terjadi sehingga menyalahkan pihak mana pun tidak ada gunanya.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dia memeriksa detail terkecil dari kontrak tersebut."', '{"tokens":["に至っては","をめぐって","に至るまで","契約書の","細部","した","念入りに","確認"],"target_translation":"Dia memeriksa detail terkecil dari kontrak tersebut.","romaji":"Keiyakusho no saibu ni itaru made nen''iri ni kakunin shita."}'::jsonb, '["契約書の","細部","に至るまで","念入りに","確認","した"]'::jsonb, '細部に至るまで berarti ''hingga ke detail-detail terkecil''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Tes Akhir Unit 1', 'Tes Akhir U1', 'n1-u1-tes-akhir', 'trophy', 25, 5) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang paling tepat untuk teks editorial ini: 多くの反対意見を押し切った結果、住民訴訟に発展する___。', '{"options":["に反した","に準じた","に先立った","に至った"],"translation":"Akibat memaksakan kehendak di tengah banyak penolakan, hal itu akhirnya berkembang hingga menjadi gugatan warga.","sentence_template":"多くの反対意見を押し切った結果、住民訴訟に発展する[blank]。"}'::jsonb, '{"selected":"に至った"}'::jsonb, '発展するに至った berarti ''akhirnya berkembang hingga mencapai tahap (gugatan warga)''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat formal berikut: 業績不振が数年続き、主力工場を閉鎖する___、経営陣は責任を取った。', '{"options":["を踏まえて","に至って","に応じて","に照らして"],"translation":"Setelah kinerja buruk berlanjut beberapa tahun hingga menutup pabrik utama, barulah manajemen mengambil tanggung jawab.","sentence_template":"業績不振が数年続き、主力工場を閉鎖する[blank]、経営陣は責任を取った。"}'::jsonb, '{"selected":"に至って"}'::jsonb, '～するに至って menunjukkan titik ekstrem (penutupan pabrik utama) yang akhirnya memicu pertanggungjawaban.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pernyataan juru bicara berikut. Apa yang sedang diselidiki oleh komite independen?', '{"audio_text":"第三者委員会は、今回の不祥事が発生するに至った組織的な原因を徹底的に調査する方針です。","options":[{"id":"opt_1","text":"Rencana ekspansi perusahaan ke pasar Eropa"},{"id":"opt_2","text":"Penyebab struktural organisasi yang mengarah pada terjadinya skandal tersebut"},{"id":"opt_3","text":"Jumlah bonus tahunan bagi para eksekutif"},{"id":"opt_4","text":"Efektivitas kampanye iklan televisi terbaru"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '発生するに至った組織的な原因 berarti ''penyebab organisasional yang berujung pada terjadinya skandal''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar analis berikut. Bagaimana sikap pembicara terhadap situasi saat ini?', '{"audio_text":"ここまでの被害が拡大した今に至っては、一時的な補助金ではなく抜本的な制度改革が不可欠だ。","options":[{"id":"opt_1","text":"Subsidi sementara sudah cukup untuk menyelesaikan masalah"},{"id":"opt_2","text":"Kerusakan yang terjadi masih sangat kecil dan terkendali"},{"id":"opt_3","text":"Reformasi sistem yang mendasar mutlak diperlukan karena kerusakan sudah telanjur meluas"},{"id":"opt_4","text":"Pemerintah sebaiknya menunggu sampai tahun depan sebelum bertindak"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '今に至っては...抜本的な制度改革が不可欠だ menegaskan bahwa reformasi sistem menyeluruh mutlak diperlukan.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Pada akhirnya, perdebatan itu berujung pada pemungutan suara."', '{"tokens":["に沿って","末","のだ","採決","に至った","議論の","長い","ながら"],"target_translation":"Pada akhirnya, perdebatan itu berujung pada pemungutan suara.","romaji":"Nagai giron no sue saiketsu ni itatta no da."}'::jsonb, '["長い","議論の","末","採決","に至った","のだ"]'::jsonb, '長い議論の末 (setelah perdebatan panjang) berujung pada 採決に至った (mencapai tahap pemungutan suara).', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan melaporkan secara transparan kronologi hingga tercapainya keputusan ini."', '{"display_text":"この結論に至った経緯を、透明性をもってご報告いたします。","romaji":"Kono ketsuron ni itatta keii wo, toumeisei wo motte go-houkoku itashimasu.","phonetic_breakdown":["ko-no","ke-tsu-ron","ni","i-ta-tta","kei-i","wo","tou-mei-sei","wo","mo-tte","go-hou-ko-ku","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"この結論に至った経緯を、透明性をもってご報告いたします。"}'::jsonb, 'Kalimat formal tingkat eksekutif yang memadukan ～に至った経緯 dengan ungkapan sopan ご報告いたします.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index) VALUES (v_level_id, 'Terpaksa Oleh Keadaan Luar (～を余儀なくされる)', 'Pahami cara menyampaikan keputusan yang terpaksa diambil akibat bencana, regulasi, atau tekanan ekonomi dalam bahasa formal N1.', 'curriculum', 2) RETURNING id INTO v_unit_id;
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kosakata Kebijakan & Restrukturisasi', 'Kosakata Restrukturisasi', 'n1-u2-kosakata', 'buildings', 15, 1) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah bisnis yang tepat: 採算が取れないため、海外市場からの___を決定した。', '{"options":["提携","進出","撤退","拡大"],"translation":"Karena tidak menguntungkan, perusahaan memutuskan penarikan diri dari pasar luar negeri.","sentence_template":"採算が取れないため、海外市場からの[blank]を決定した。"}'::jsonb, '{"selected":"撤退"}'::jsonb, '撤退 (tettai) berarti ''penarikan diri/mundur'' dari pasar atau bisnis tertentu.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berita industri berikut: 部品の供給が途絶え、工場の___が続いている。', '{"options":["設備投資","大量生産","新規採用","操業停止"],"translation":"Pasokan suku cadang terputus, dan penghentian operasi pabrik terus berlanjut.","sentence_template":"部品の供給が途絶え、工場の[blank]が続いている。"}'::jsonb, '{"selected":"操業停止"}'::jsonb, '操業停止 (sougyou teishi) berarti ''penghentian operasional pabrik/produksi''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat untuk konteks pemerintahan daerah: 深刻な___により、公共施設の新設が見送られた。', '{"options":["増収","好景気","財政難","黒字化"],"translation":"Akibat kesulitan keuangan yang serius, pembangunan fasilitas publik baru ditunda.","sentence_template":"深刻な[blank]により、公共施設の新設が見送られた。"}'::jsonb, '{"selected":"財政難"}'::jsonb, '財政難 (zaiseinan) berarti ''kesulitan fiskal/keuangan'' pada pemerintah atau lembaga.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan berikut. Langkah apa yang diambil manajemen untuk memulihkan kondisi?', '{"audio_text":"業績悪化を受け、当社は不採算部門の整理を含む大規模な経営再建に着手いたします。","options":[{"id":"opt_1","text":"Memulai restrukturisasi manajemen skala besar termasuk penataan divisi yang merugi"},{"id":"opt_2","text":"Membagikan dividen khusus kepada seluruh pemegang saham"},{"id":"opt_3","text":"Membuka sepuluh cabang baru di seluruh Jepang"},{"id":"opt_4","text":"Menaikkan harga semua produk sebesar lima puluh persen"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '不採算部門の整理 (penataan divisi tidak menguntungkan) dan 経営再建 (restrukturisasi manajemen).', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan laporan cuaca berikut. Apa dampak langsung dari angin topan tersebut?', '{"audio_text":"大型台風の接近に伴い、沿岸部の住民には早急な避難が呼びかけられています。","options":[{"id":"opt_1","text":"Seluruh pelabuhan dibuka untuk wisata akhir pekan"},{"id":"opt_2","text":"Warga di wilayah pesisir diimbau segera melakukan evakuasi"},{"id":"opt_3","text":"Curah hujan diperkirakan jauh lebih rendah dari rata-rata"},{"id":"opt_4","text":"Transportasi kereta cepat beroperasi lebih cepat dari jadwal"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '沿岸部の住民には早急な避難が呼びかけられています berarti ''warga pesisir diimbau segera mengungsi/evakuasi''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami sedang meninjau ulang perubahan arah kebijakan secara menyeluruh."', '{"display_text":"抜本的な方針転換を検討しているところです。","romaji":"Bapponteki na houshin tenkan wo kentou shite iru tokoro desu.","phonetic_breakdown":["ba-ppon-te-ki","na","hou-shin","ten-kan","wo","ken-tou","shi-te","i-ru","to-ko-ro","de-su"]}'::jsonb, '{"expected_transcript":"抜本的な方針転換を検討しているところです。"}'::jsonb, '方針転換 (houshin tenkan) berarti ''perubahan haluan/arah kebijakan''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Pola ～を余儀なくされる', 'Pola 余儀なくされる', 'n1-u2-pola-utama', 'sparkle', 20, 2) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berita berikut: 悪天候のため、国際会議の日程変更___。', '{"options":["を皮切りにした","を契機にした","をよそにした","を余儀なくされた"],"translation":"Akibat cuaca buruk, konferensi internasional terpaksa mengubah jadwalnya.","sentence_template":"悪天候のため、国際会議の日程変更[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, 'Kata benda + を余儀なくされる menyatakan terpaksa melakukan sesuatu karena keadaan eksternal yang tidak terelakkan.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk kausatif yang tepat untuk kalimat berikut: 原材料費の高騰が、メーカー各社に値上げ___。', '{"options":["を余儀なくさせている","に至っている","を禁じ得ない","を余儀なくされている"],"translation":"Lonjakan harga bahan baku memaksa berbagai perusahaan manufaktur untuk menaikkan harga.","sentence_template":"原材料費の高騰が、メーカー各社に値上げ[blank]。"}'::jsonb, '{"selected":"を余儀なくさせている"}'::jsonb, 'Jika subjeknya adalah penyebab eksternal (原材料費の高騰), gunakan bentuk kausatif ～に...を余儀なくさせる.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan pola yang benar: 震災により、多くの被災者が長期の避難生活___。', '{"options":["を前提としている","を対象としている","を余儀なくされている","を軸としている"],"translation":"Akibat gempa besar, banyak korban bencana terpaksa menjalani kehidupan pengungsian jangka panjang.","sentence_template":"震災により、多くの被災者が長期の避難生活[blank]。"}'::jsonb, '{"selected":"を余儀なくされている"}'::jsonb, '～を余儀なくされている menggambarkan kondisi keterpaksaan yang masih berlangsung hingga kini.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Akibat kekurangan dana, proyek itu terpaksa dihentikan."', '{"tokens":["により","のだ","中止","計画は","ながら","資金不足","を余儀なくされた","に至った"],"target_translation":"Akibat kekurangan dana, proyek itu terpaksa dihentikan.","romaji":"Shikin busoku ni yori keikaku wa chuushi wo yoginaku sareta no da."}'::jsonb, '["資金不足","により","計画は","中止","を余儀なくされた","のだ"]'::jsonb, '中止を余儀なくされた berarti ''terpaksa dibatalkan/dihentikan''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Perubahan regulasi memaksa kami meninjau ulang strategi."', '{"tokens":["見直し","規制の","を余儀なく","された","戦略の","強化で","をめぐって","ばかりに"],"target_translation":"Perubahan regulasi memaksa kami meninjau ulang strategi.","romaji":"Kisei no kyouka de senryaku no minaoshi wo yoginaku sareta."}'::jsonb, '["規制の","強化で","戦略の","見直し","を余儀なく","された"]'::jsonb, '戦略の見直しを余儀なくされた berarti ''terpaksa meninjau ulang strategi''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena cedera, atlet tersebut terpaksa mengundurkan diri dari turnamen."', '{"display_text":"負傷のため、その選手は大会からの棄権を余儀なくされた。","romaji":"Fushou no tame, sono senshu wa taikai kara no kiken wo yoginaku sareta.","phonetic_breakdown":["fu-shou","no","ta-me","so-no","sen-shu","wa","tai-kai","ka-ra","no","ki-ken","wo","yo-gi-na-ku","sa-re-ta"]}'::jsonb, '{"expected_transcript":"負傷のため、その選手は大会からの棄権を余儀なくされた。"}'::jsonb, '棄権を余儀なくされた adalah kolokasi berita olahraga yang sangat umum untuk ''terpaksa mundur/walkover''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Berita Bencana & Kebijakan Publik', 'Dengar & Baca U2', 'n1-u2-dengar-baca', 'play-circle', 20, 3) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan berita ekonomi berikut. Apa yang terpaksa dilakukan oleh perusahaan manufaktur tersebut?', '{"audio_text":"半導体不足の長期化により、自動車メーカー各社は大幅な減産を余儀なくされている。","options":[{"id":"opt_1","text":"Meningkatkan ekspor mobil listrik ke Amerika Serikat"},{"id":"opt_2","text":"Membangun pabrik semikonduktor baru dalam satu bulan"},{"id":"opt_3","text":"Terpaksa memangkas produksi secara signifikan akibat kelangkaan semikonduktor"},{"id":"opt_4","text":"Menurunkan harga jual seluruh lini kendaraan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '大幅な減産を余儀なくされている berarti ''terpaksa melakukan pengurangan produksi besar-besaran''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan laporan transportasi berikut. Mengapa jadwal penerbangan terganggu?', '{"audio_text":"記録的な大雪の影響で、多数の便が欠航や大幅な遅延を余儀なくされました。","options":[{"id":"opt_1","text":"Terjadi pemogokan staf bandara selama dua hari"},{"id":"opt_2","text":"Landasan pacu sedang menjalani renovasi terjadwal"},{"id":"opt_3","text":"Sistem reservasi tiket mengalami gangguan jaringan"},{"id":"opt_4","text":"Salju lebat yang mencetak rekor memaksa banyak penerbangan dibatalkan atau tertunda lama"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '記録的な大雪の影響で (akibat salju lebat pemecah rekor) menyebabkan 欠航や大幅な遅延を余儀なくされました.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan analis pasar berikut. Apa tekanan utama yang dihadapi sektor ritel?', '{"audio_text":"急激な円安と人件費の上昇が、小売業界にビジネスモデルの転換を余儀なくさせている。","options":[{"id":"opt_1","text":"Pelemahan yen yang tajam dan kenaikan biaya tenaga kerja memaksa perubahan model bisnis"},{"id":"opt_2","text":"Penurunan jumlah wisatawan asing secara mendadak"},{"id":"opt_3","text":"Kelebihan pasokan tenaga kerja di sektor ritel"},{"id":"opt_4","text":"Penghapusan pajak konsumsi oleh pemerintah pusat"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '急激な円安と人件費の上昇 memaksa sektor ritel melakukan ビジネスモデルの転換.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi berita berikut: 感染症の拡大を受け、多くの飲食店が営業時間の短縮___。', '{"options":["を顧みなかった","を皮切りにした","を余儀なくされた","をものともしなかった"],"translation":"Menyusul meluasnya penyakit menular, banyak restoran terpaksa mempersingkat jam operasionalnya.","sentence_template":"感染症の拡大を受け、多くの飲食店が営業時間の短縮[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, '営業時間の短縮を余儀なくされた adalah ungkapan berita yang sangat natural untuk ''terpaksa memendekkan jam buka''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata benda yang paling alami sebelum を余儀なくされる: 建物の老朽化により、図書館は一時___を余儀なくされた。', '{"options":["閉館","入館","開館","来館"],"translation":"Akibat penuaan bangunan, perpustakaan terpaksa ditutup sementara.","sentence_template":"建物の老朽化により、図書館は一時[blank]を余儀なくされた。"}'::jsonb, '{"selected":"閉館"}'::jsonb, '一時閉館を余儀なくされた berarti ''terpaksa ditutup sementara'' karena bangunan tua (老朽化).', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予期せぬ法改正が、企業に大規模なシステム改修___。', '{"options":["を余儀なくさせた","に至らせた","を余儀なくされた","に足らしめた"],"translation":"Revisi undang-undang yang tak terduga memaksa perusahaan melakukan perombakan sistem berskala besar.","sentence_template":"予期せぬ法改正が、企業に大規模なシステム改修[blank]。"}'::jsonb, '{"selected":"を余儀なくさせた"}'::jsonb, 'Subjeknya 予期せぬ法改正 (penyebab) dan objek penerimanya 企業に, sehingga menggunakan bentuk kausatif を余儀なくさせた.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Bicara & Rakit Laporan Keterpaksaan', 'Bicara & Rakit U2', 'n1-u2-bicara-rakit', 'microphone', 20, 4) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena kekurangan tenaga kerja, beberapa layanan terpaksa dikurangi."', '{"display_text":"人手不足により、一部サービスの縮小を余儀なくされています。","romaji":"Hitode busoku ni yori, ichibu saabisu no shukushou wo yoginaku sarete imasu.","phonetic_breakdown":["hi-to-de","bu-so-ku","ni","yo-ri","i-chi-bu","saa-bi-su","no","shu-ku-shou","wo","yo-gi-na-ku","sa-re-te","i-ma-su"]}'::jsonb, '{"expected_transcript":"人手不足により、一部サービスの縮小を余儀なくされています。"}'::jsonb, '縮小を余儀なくされています (terpaksa diperkecil/dikurangi) lazim dipakai dalam pengumuman resmi layanan.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Akibat pemadaman listrik mendadak, kereta terpaksa berhenti beroperasi."', '{"display_text":"突然の停電で、列車は運転見合わせを余儀なくされた。","romaji":"Totsuzen no teiden de, ressha wa unten miawase wo yoginaku sareta.","phonetic_breakdown":["to-tsu-zen","no","tei-den","de","re-ssha","wa","un-ten","mi-a-wa-se","wo","yo-gi-na-ku","sa-re-ta"]}'::jsonb, '{"expected_transcript":"突然の停電で、列車は運転見合わせを余儀なくされた。"}'::jsonb, '運転見合わせ (unten miawase) adalah istilah perkeretaapian Jepang untuk ''penangguhan sementara operasional kereta''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Banjir besar memaksa ratusan keluarga mengungsi ke tempat penampungan."', '{"display_text":"大規模な洪水により、数百世帯が避難所への移動を余儀なくされた。","romaji":"Daikibo na kouzui ni yori, suuhyaku setai ga hinanjo e no idou wo yoginaku sareta.","phonetic_breakdown":["dai-ki-bo","na","kou-zui","ni","yo-ri","suu-hya-ku","se-tai","ga","hi-nan-jo","e","no","i-dou","wo","yo-gi-na-ku","sa-re-ta"]}'::jsonb, '{"expected_transcript":"大規模な洪水により、数百世帯が避難所への移動を余儀なくされた。"}'::jsonb, '数百世帯 (suuhyaku setai: ratusan rumah tangga) dan 避難所への移動 (perpindahan ke tempat pengungsian).', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Perusahaan terpaksa memangkas jumlah karyawan akibat krisis."', '{"tokens":["当社は","された","により","どころか","を余儀なく","に至って","人員削減","経営危機"],"target_translation":"Perusahaan terpaksa memangkas jumlah karyawan akibat krisis.","romaji":"Keiei kiki ni yori tousha wa jin''in sakugen wo yoginaku sareta."}'::jsonb, '["経営危機","により","当社は","人員削減","を余儀なく","された"]'::jsonb, '人員削減を余儀なくされた berarti ''terpaksa melakukan pengurangan karyawan''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kenaikan biaya logistik memaksa perubahan tarif pengiriman."', '{"tokens":["に先立ち","高騰が","改定","させた","ながら","を余儀なく","物流費の","配送料の"],"target_translation":"Kenaikan biaya logistik memaksa perubahan tarif pengiriman.","romaji":"Butsuryuuhi no koutou ga haisouryou no kaitei wo yoginaku saseta."}'::jsonb, '["物流費の","高騰が","配送料の","改定","を余儀なく","させた"]'::jsonb, '物流費の高騰 (lonjakan biaya logistik) sebagai subjek memaksa 配送料の改定 (revisi ongkos kirim).', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena gempa susulan, pekerjaan pemulihan terpaksa ditunda."', '{"tokens":["中断","復旧作業は","をめぐって","余震の","影響で","を余儀なく","されている","ばかりに"],"target_translation":"Karena gempa susulan, pekerjaan pemulihan terpaksa ditunda.","romaji":"Yoshin no eikyou de fukkyuu sagyou wa chuudan wo yoginaku sarete iru."}'::jsonb, '["余震の","影響で","復旧作業は","中断","を余儀なく","されている"]'::jsonb, '復旧作業 (pekerjaan pemulihan) terpaksa dihentikan sementara (中断を余儀なくされている).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Tes Akhir Unit 2', 'Tes Akhir U2', 'n1-u2-tes-akhir', 'trophy', 25, 5) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 主要取引先の倒産により、当社も資金計画の大幅な修正___。', '{"options":["を前提とした","をものともしなかった","を余儀なくされた","を契機とした"],"translation":"Akibat kebangkrutan mitra bisnis utama, perusahaan kami pun terpaksa merevisi besar-besaran rencana keuangan.","sentence_template":"主要取引先の倒産により、当社も資金計画の大幅な修正[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, 'Kebangkrutan mitra utama adalah faktor eksternal yang memaksa revisi besar rencana keuangan (修正を余儀なくされた).', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat formal berikut: 予算の大幅削減が、研究チームに実験規模の縮小___。', '{"options":["に至った","を余儀なくされた","に足った","を余儀なくさせた"],"translation":"Pemangkasan anggaran besar-besaran memaksa tim peneliti memperkecil skala eksperimen.","sentence_template":"予算の大幅削減が、研究チームに実験規模の縮小[blank]。"}'::jsonb, '{"selected":"を余儀なくさせた"}'::jsonb, 'Subjek penyebab (予算の大幅削減が) menuntut bentuk kausatif ～を余儀なくさせた.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan berita berikut. Mengapa festival tradisional itu dibatalkan?', '{"audio_text":"安全確保が困難と判断されたため、今年の伝統祭りはやむを得ず中止を余儀なくされた。","options":[{"id":"opt_1","text":"Jumlah peserta tahun ini jauh lebih sedikit dari target"},{"id":"opt_2","text":"Dinilai sulit menjamin keselamatan sehingga terpaksa dibatalkan"},{"id":"opt_3","text":"Panitia ingin menggantinya dengan konser musik modern"},{"id":"opt_4","text":"Lokasi festival sedang digunakan untuk acara olahraga"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '安全確保が困難と判断されたため (karena dinilai sulit menjamin keamanan) menyebabkan 中止を余儀なくされた.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan industri berikut. Apa situasi yang dihadapi perusahaan percetakan lokal?', '{"audio_text":"デジタル化の急速な進展により、地域の老舗印刷会社は事業転換を余儀なくされている。","options":[{"id":"opt_1","text":"Mereka menerima pesanan buku cetak terbanyak sepanjang sejarah"},{"id":"opt_2","text":"Mereka mendapat subsidi penuh dari pemerintah untuk membeli mesin cetak baru"},{"id":"opt_3","text":"Digitalisasi pesat memaksa mereka mengubah lini bisnis"},{"id":"opt_4","text":"Mereka menolak menggunakan komputer di seluruh kantor"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '事業転換を余儀なくされている berarti ''terpaksa mengalihkan/mengubah bidang usaha''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Akibat kekeringan berkepanjangan, para petani terpaksa membatasi penggunaan air."', '{"tokens":["干ばつで","取水制限","ながら","長引く","を余儀なく","農家は","に至っては","された"],"target_translation":"Akibat kekeringan berkepanjangan, para petani terpaksa membatasi penggunaan air.","romaji":"Nagabiku kanbatsu de nouka wa shusui seigen wo yoginaku sareta."}'::jsonb, '["長引く","干ばつで","農家は","取水制限","を余儀なく","された"]'::jsonb, '長引く干ばつ (kekeringan berkepanjangan) memaksa 取水制限 (pembatasan pengambilan air).', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami mohon maaf karena terpaksa menunda jadwal pengiriman."', '{"display_text":"配送予定の延期を余儀なくされましたことを、深くお詫び申し上げます。","romaji":"Haisou yotei no enki wo yoginaku saremashita koto wo, fukaku owabi moushiagemasu.","phonetic_breakdown":["hai-sou","yo-tei","no","en-ki","wo","yo-gi-na-ku","sa-re-ma-shi-ta","ko-to","wo","fu-ka-ku","o-wa-bi","mou-shi-a-ge-ma-su"]}'::jsonb, '{"expected_transcript":"配送予定の延期を余儀なくされましたことを、深くお詫び申し上げます。"}'::jsonb, 'Penggunaan ～を余儀なくされました dalam surat atau pernyataan permintaan maaf resmi perusahaan.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index) VALUES (v_level_id, 'Meskipun Memang Demikian (～とはいえ)', 'Bangun argumen tajuk rencana, evaluasi berimbang, dan kritik bernuansa dengan mengakui fakta terlebih dahulu sebelum menyampaikan catatan penting.', 'curriculum', 3) RETURNING id INTO v_unit_id;
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kosakata Opini & Evaluasi Publik', 'Kosakata Opini', 'n1-u3-kosakata', 'scales', 15, 1) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 新しい税制案については、国民の間で___が分かれている。', '{"options":["勝負","有無","高低","賛否"],"translation":"Mengenai rancangan sistem pajak baru, pro dan kontra terbelah di kalangan masyarakat.","sentence_template":"新しい税制案については、国民の間で[blank]が分かれている。"}'::jsonb, '{"selected":"賛否"}'::jsonb, '賛否が分かれる (sanpi ga wakareru) berarti ''pendapat setuju dan tidak setuju terbelah''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi kebijakan berikut: 理念は立派だが、現場での___に疑問が残る。', '{"options":["装飾性","娯楽性","偶然性","実効性"],"translation":"Prinsipnya memang mulia, tetapi efektivitas penerapannya di lapangan masih menyisakan keraguan.","sentence_template":"理念は立派だが、現場での[blank]に疑問が残る。"}'::jsonb, '{"selected":"実効性"}'::jsonb, '実効性 (jikkousei) berarti ''efektivitas nyata / daya laksana'' suatu aturan atau kebijakan.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk wacana lingkungan dan ekonomi: 長期的な視点から、事業の___を高める必要がある。', '{"options":["即時性","排他性","持続可能性","曖昧性"],"translation":"Dari sudut pandang jangka panjang, perlu meningkatkan keberlanjutan bisnis.","sentence_template":"長期的な視点から、事業の[blank]を高める必要がある。"}'::jsonb, '{"selected":"持続可能性"}'::jsonb, '持続可能性 (jizoku kanousei) adalah padanan resmi untuk ''sustainability / keberlanjutan''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan komentar berita berikut. Bagaimana sifat dari kebijakan yang baru diumumkan?', '{"audio_text":"今回導入された支援策はあくまで暫定措置であり、来年度には抜本的な見直しが予定されている。","options":[{"id":"opt_1","text":"Kebijakan permanen yang tidak akan diubah selama sepuluh tahun"},{"id":"opt_2","text":"Langkah sementara yang akan ditinjau ulang secara mendasar tahun fiskal depan"},{"id":"opt_3","text":"Program sukarela yang hanya berlaku bagi perusahaan asing"},{"id":"opt_4","text":"Aturan lama yang sudah dicabut sejak tahun lalu"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, 'あくまで暫定措置であり berarti ''hanya merupakan langkah sementara (provisional measure)''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan diskusi berikut. Apa tantangan yang ditekankan pembicara?', '{"audio_text":"技術革新によって業務効率は飛躍的に向上したが、倫理面では依然として課題が山積している。","options":[{"id":"opt_1","text":"Efisiensi kerja menurun drastis sejak teknologi baru diterapkan"},{"id":"opt_2","text":"Semua persoalan etika telah sepenuhnya terselesaikan"},{"id":"opt_3","text":"Dari sisi etika, masih banyak sekali permasalahan yang menumpuk"},{"id":"opt_4","text":"Biaya perangkat keras menjadi semakin murah setiap tahun"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '課題が山積している (kadai ga sanseki shite iru) berarti ''masalah/tantangan menumpuk bagai gunung''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kita perlu mempertimbangkan persoalan ini dari berbagai sudut pandang."', '{"display_text":"この問題は多角的な視点から検討する必要がある。","romaji":"Kono mondai wa takakuteki na shiten kara kentou suru hitsuyou ga aru.","phonetic_breakdown":["ko-no","mon-dai","wa","ta-ka-ku-te-ki","na","shi-ten","ka-ra","ken-tou","su-ru","hi-tsu-you","ga","a-ru"]}'::jsonb, '{"expected_transcript":"この問題は多角的な視点から検討する必要がある。"}'::jsonb, '多角的な視点 (takakuteki na shiten) berarti ''sudut pandang multidimensi/beragam''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Pola ～とはいえ & Kontrasnya', 'Pola ～とはいえ', 'n1-u3-pola-utama', 'sparkle', 20, 2) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat opini berikut: 景気が回復傾向にある___、地方の中小企業にはまだ恩恵が届いていない。', '{"options":["とはいえ","ともなると","とあって","とばかりに"],"translation":"Meskipun ekonomi memang cenderung pulih, manfaatnya belum sampai ke UKM di daerah.","sentence_template":"景気が回復傾向にある[blank]、地方の中小企業にはまだ恩恵が届いていない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '～とはいえ mengakui fakta di klausa pertama (''memang benar bahwa...''), lalu menyampaikan kenyataan yang bertolak belakang atau catatan penting.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk mengakui status/kondisi: 初心者___、基本的な安全ルールは必ず守らなければならない。', '{"options":["なりに","とはいえ","に足る","を皮切りに"],"translation":"Meskipun memang pemula, aturan keselamatan dasar tetap wajib dipatuhi.","sentence_template":"初心者[blank]、基本的な安全ルールは必ず守らなければならない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, 'Kata benda + とはいえ (''meski memang berstatus...'') menekankan bahwa pengecualian tidak berlaku.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan konjungsi formal yang setara: リモートワークが普及した___、対面での議論の重要性は変わらない。', '{"options":["といえども","とは限らず","と相まって","とはいうものの"],"translation":"Walaupun kerja jarak jauh telah meluas, pentingnya diskusi tatap muka tetap tidak berubah.","sentence_template":"リモートワークが普及した[blank]、対面での議論の重要性は変わらない。"}'::jsonb, '{"selected":"とはいうものの"}'::jsonb, 'とはいうものの memiliki nuansa konsesif yang sangat dekat dengan とはいえ, lazim digunakan dalam esai dan editorial.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun musim semi telah tiba, pagi dan malam masih dingin."', '{"tokens":["とはいえ","に至って","冷え込む","春に","朝晩は","ながら","なった","まだ"],"target_translation":"Meskipun musim semi telah tiba, pagi dan malam masih dingin.","romaji":"Haru ni natta to wa ie, asaban wa mada hiekomu."}'::jsonb, '["春に","なった","とはいえ","朝晩は","まだ","冷え込む"]'::jsonb, '春になったとはいえ (meski memang sudah musim semi) diikuti fakta kontras 朝晩はまだ冷え込む.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Walaupun hanya sementara, beban biaya tetaplah besar."', '{"tokens":["を余儀なく","負担は","一時的","とはいえ","費用の","軽くない","決して","ばかりに"],"target_translation":"Walaupun hanya sementara, beban biaya tetaplah besar.","romaji":"Ichijiteki to wa ie, hiyou no futan wa kesshite karukunai."}'::jsonb, '["一時的","とはいえ","費用の","負担は","決して","軽くない"]'::jsonb, 'Kata sifat-na (tanpa だ atau dengan だ) + とはいえ: 一時的とはいえ (''meski hanya sementara'').', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun memang sudah terbiasa, tidak boleh lengah sedikit pun."', '{"display_text":"慣れた作業とはいえ、一瞬の油断も許されない。","romaji":"Nareta sagyou to wa ie, isshun no yudan mo yurusarenai.","phonetic_breakdown":["na-re-ta","sa-gyou","to","wa","i-e","i-sshun","no","yu-dan","mo","yu-ru-sa-re-nai"]}'::jsonb, '{"expected_transcript":"慣れた作業とはいえ、一瞬の油断も許されない。"}'::jsonb, '一瞬の油断も許されない berarti ''kelengahan sesaat pun tidak dapat ditoleransi''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Tajuk Rencana & Evaluasi Berimbang', 'Dengar & Baca U3', 'n1-u3-dengar-baca', 'play-circle', 20, 3) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan tajuk rencana berikut. Apa kekhawatiran penulis terhadap penggunaan AI?', '{"audio_text":"生成AIの精度が飛躍的に高まったとはいえ、情報の真偽を最終的に判断するのは人間でなければならない。","options":[{"id":"opt_1","text":"Akurasi AI generatif justru semakin menurun"},{"id":"opt_2","text":"Manusia tetap harus menjadi penentu akhir kebenaran informasi"},{"id":"opt_3","text":"AI generatif sebaiknya dilarang sepenuhnya di sektor pendidikan"},{"id":"opt_4","text":"Biaya pengembangan AI terlalu rendah untuk diawasi"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '情報の真偽を最終的に判断するのは人間でなければならない berarti ''yang memutuskan benar-salahnya informasi pada akhirnya haruslah manusia''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan ulasan ekonomi berikut. Bagaimana penilaian pembicara terhadap kenaikan gaji tahun ini?', '{"audio_text":"大手企業を中心に賃上げが進んだとはいえ、物価上昇のペースには依然として追いついていない。","options":[{"id":"opt_1","text":"Kenaikan gaji belum mampu mengejar laju kenaikan harga barang"},{"id":"opt_2","text":"Harga barang menurun drastis berkat kenaikan gaji"},{"id":"opt_3","text":"Perusahaan besar menolak menaikkan gaji karyawan"},{"id":"opt_4","text":"Daya beli masyarakat meningkat dua kali lipat"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '物価上昇のペースには依然として追いついていない berarti ''tetap belum mengejar laju inflasi/kenaikan harga''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pendapat pakar pendidikan berikut. Apa pesan utamanya?', '{"audio_text":"オンライン教材が充実してきたとはいえ、教師と生徒の直接的な対話に代わるものはない。","options":[{"id":"opt_1","text":"Materi daring masih sangat kurang dan sulit diakses"},{"id":"opt_2","text":"Sekolah tatap muka akan segera dihapuskan"},{"id":"opt_3","text":"Dialog langsung antara guru dan siswa tidak tergantikan meski materi daring lengkap"},{"id":"opt_4","text":"Siswa belajar lebih cepat tanpa bantuan guru sama sekali"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '直接的な対話に代わるものはない berarti ''tidak ada yang dapat menggantikan dialog langsung''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi paragraf analisis berikut: 人口減少への対策が急務である___、即効性のある解決策は容易に見つからない。', '{"options":["とばかりに","とあって","とはいえ","ともなると"],"translation":"Meskipun penanggulangan penurunan populasi memang mendesak, solusi yang berdampak instan tidak mudah ditemukan.","sentence_template":"人口減少への対策が急務である[blank]、即効性のある解決策は容易に見つからない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '急務であるとはいえ mengakui urgensi masalah, lalu menyoroti kesulitan menemukan solusi instan.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih ungkapan yang tepat: 個人的な見解___、影響力のある立場の発言には慎重さが求められる。', '{"options":["とはいえ","をもって","に足る","なりに"],"translation":"Meskipun itu memang pendapat pribadi, pernyataan dari posisi yang berpengaruh menuntut kehati-hatian.","sentence_template":"個人的な見解[blank]、影響力のある立場の発言には慎重さが求められる。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '個人的な見解とはいえ (''meski itu pendapat pribadi'') sering muncul dalam diskusi etika publik.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 試験の合格率が上昇した___、問題の難易度自体が下がったわけではない。', '{"options":["に沿って","に至って","をよそに","とはいえ"],"translation":"Walaupun tingkat kelulusan ujian meningkat, bukan berarti tingkat kesulitan soalnya sendiri menurun.","sentence_template":"試験の合格率が上昇した[blank]、問題の難易度自体が下がったわけではない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '～とはいえ...わけではない adalah kombinasi klasik N1 untuk meluruskan kesalahpahaman umum.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Bicara & Rakit Argumen Berimbang', 'Bicara & Rakit U3', 'n1-u3-bicara-rakit', 'microphone', 20, 4) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun anggarannya terbatas, kualitas tidak boleh diturunkan."', '{"display_text":"予算が限られているとはいえ、品質を落とすわけにはいかない。","romaji":"Yosan ga kagirarete iru to wa ie, hinshitsu wo otosu wake ni wa ikanai.","phonetic_breakdown":["yo-san","ga","ka-gi-ra-re-te","i-ru","to","wa","i-e","hin-shi-tsu","wo","o-to-su","wa-ke","ni","wa","i-ka-nai"]}'::jsonb, '{"expected_transcript":"予算が限られているとはいえ、品質を落とすわけにはいかない。"}'::jsonb, 'Memadukan ～とはいえ dengan ～わけにはいかない (tidak bisa/tidak boleh melakukan...).', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Walaupun disebut proyek kecil, dampaknya sangat luas."', '{"display_text":"小規模な事業とはいえ、地域社会への波及効果は大きい。","romaji":"Shoukibo na jigyou to wa ie, chiiki shakai e no hakyuu kouka wa ookii.","phonetic_breakdown":["shou-ki-bo","na","ji-gyou","to","wa","i-e","chi-i-ki","sha-kai","e","no","ha-kyuu","kou-ka","wa","oo-kii"]}'::jsonb, '{"expected_transcript":"小規模な事業とはいえ、地域社会への波及効果は大きい。"}'::jsonb, '波及効果 (hakyuu kouka) berarti ''efek berantai / ripple effect''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meski memang hari libur, saya tetap harus memeriksa email darurat."', '{"display_text":"休日とはいえ、緊急の連絡には対応できるようにしている。","romaji":"Kyuujitsu to wa ie, kinkyu no renraku ni wa taiou dekiru you ni shite iru.","phonetic_breakdown":["kyuu-ji-tsu","to","wa","i-e","kin-kyuu","no","ren-ra-ku","ni","wa","tai-ou","de-ki-ru","you","ni","shi-te","i-ru"]}'::jsonb, '{"expected_transcript":"休日とはいえ、緊急の連絡には対応できるようにしている。"}'::jsonb, '休日とはいえ (meski memang hari libur) diikuti sikap profesional tetap siap merespons kontak darurat.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun memang sudah berpengalaman, persiapan yang matang tetap penting."', '{"tokens":["ばかりに","準備は","豊富だ","欠かせない","とはいえ","経験が","に至って","事前の"],"target_translation":"Meskipun memang sudah berpengalaman, persiapan yang matang tetap penting.","romaji":"Keiken ga houfu da to wa ie, jizen no junbi wa kakasenai."}'::jsonb, '["経験が","豊富だ","とはいえ","事前の","準備は","欠かせない"]'::jsonb, '経験が豊富だとはいえ (meski berpengalaman luas) diikuti 事前の準備は欠かせない (persiapan sebelumnya tak tergantikan).', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Walaupun tingkat kriminalitas rendah, kewaspadaan tidak boleh kendur."', '{"tokens":["をめぐって","緩めては","なりに","ならない","とはいえ","良い","防犯意識を","治安が"],"target_translation":"Walaupun tingkat kriminalitas rendah, kewaspadaan tidak boleh kendur.","romaji":"Chian ga yoi to wa ie, bouhan ishiki wo yurumete wa naranai."}'::jsonb, '["治安が","良い","とはいえ","防犯意識を","緩めては","ならない"]'::jsonb, '防犯意識を緩めてはならない berarti ''kesadaran pencegahan kejahatan tidak boleh dikendurkan''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun hasilnya belum sempurna, kemajuan besar telah tercapai."', '{"tokens":["どころか","を余儀なく","遂げた","とはいえ","完璧では","ない","大きな","前進を"],"target_translation":"Meskipun hasilnya belum sempurna, kemajuan besar telah tercapai.","romaji":"Kanpeki de wa nai to wa ie, ookina zenshin wo togeta."}'::jsonb, '["完璧では","ない","とはいえ","大きな","前進を","遂げた"]'::jsonb, '大きな前進を遂げた berarti ''telah mencapai kemajuan besar''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Tes Akhir Unit 3', 'Tes Akhir U3', 'n1-u3-tes-akhir', 'trophy', 25, 5) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk melengkapi opini berikut: 制度の理念には賛同する___、導入時期については再考の余地がある。', '{"options":["ともなると","とあって","とばかりに","とはいえ"],"translation":"Meskipun saya setuju dengan prinsip sistemnya, soal waktu penerapannya masih ada ruang untuk dipertimbangkan ulang.","sentence_template":"制度の理念には賛同する[blank]、導入時期については再考の余地がある。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '賛同するとはいえ mengakui persetujuan secara prinsip sebelum mengajukan catatan soal jadwal implementasi.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 自由競争が原則である___、消費者保護のための一定の規制は必要だ。', '{"options":["に足る","をもって","に至っては","とはいえ"],"translation":"Meskipun persaingan bebas adalah prinsipnya, regulasi tertentu untuk perlindungan konsumen tetap diperlukan.","sentence_template":"自由競争が原則である[blank]、消費者保護のための一定の規制は必要だ。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '自由競争が原則であるとはいえ menyusun argumen berimbang yang sangat khas dalam bacaan N1.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar rapat berikut. Apa catatan kritis yang disampaikan pembicara?', '{"audio_text":"新製品の売れ行きが好調とはいえ、競合他社の動向を注視し続けなければ市場シェアを失いかねない。","options":[{"id":"opt_1","text":"Penjualan produk baru sangat buruk sejak hari pertama"},{"id":"opt_2","text":"Perusahaan tidak memiliki pesaing di pasar saat ini"},{"id":"opt_3","text":"Pangsa pasar dapat hilang jika tidak terus memantau gerak-gerik kompetitor"},{"id":"opt_4","text":"Harga produk baru harus segera dinaikkan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '競合他社の動向を注視し続けなければ市場シェアを失いかねない mengingatkan agar tetap waspada terhadap pesaing.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan kebijakan energi berikut. Apa poin utama yang ditekankan pembicara?', '{"audio_text":"再生可能エネルギーの導入が進んだとはいえ、安定供給の確保にはまだ多くの技術的課題が残っている。","options":[{"id":"opt_1","text":"Energi terbarukan belum mulai diterapkan sama sekali"},{"id":"opt_2","text":"Pasokan energi terbarukan sudah sepenuhnya stabil tanpa kendala"},{"id":"opt_3","text":"Biaya listrik turun drastis di seluruh wilayah"},{"id":"opt_4","text":"Masih banyak tantangan teknis untuk menjamin pasokan yang stabil"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '安定供給の確保にはまだ多くの技術的課題が残っている menyoroti tantangan teknis stabilitas pasokan.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Walaupun hanya perbedaan kecil, dalam jangka panjang pengaruhnya besar."', '{"tokens":["大きな","に至って","差だ","なりに","長期的には","影響が出る","とはいえ","わずかな"],"target_translation":"Walaupun hanya perbedaan kecil, dalam jangka panjang pengaruhnya besar.","romaji":"Wazuka na sa da to wa ie, choukiteki ni wa ookina eikyou ga deru."}'::jsonb, '["わずかな","差だ","とはいえ","長期的には","大きな","影響が出る"]'::jsonb, 'わずかな差だとはいえ mengakui perbedaannya kecil, lalu menekankan dampak jangka panjangnya.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun ini baru tahap awal, hasil yang menjanjikan sudah mulai terlihat."', '{"display_text":"まだ初期段階とはいえ、確かな手応えが感じられる。","romaji":"Mada shoki dankai to wa ie, tashika na tegotae ga kanjirareru.","phonetic_breakdown":["ma-da","sho-ki","dan-kai","to","wa","i-e","ta-shi-ka","na","te-go-ta-e","ga","kan-ji-ra-re-ru"]}'::jsonb, '{"expected_transcript":"まだ初期段階とはいえ、確かな手応えが感じられる。"}'::jsonb, '確かな手応え (tashika na tegotae) berarti ''respons/hasil nyata yang menjanjikan''.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index) VALUES (v_level_id, 'Dengan Sarana Resmi / Batas Waktu (～をもって)', 'Gunakan ungkapan super-formal untuk pengumuman resmi, batas akhir pendaftaran, surat menyurat korporasi, dan prosedur hukum.', 'curriculum', 4) RETURNING id INTO v_unit_id;
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kosakata Pengumuman & Surat Resmi', 'Kosakata Resmi', 'n1-u4-kosakata', 'briefcase', 15, 1) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk surat resmi: 審査の結果は、後日___にてご連絡いたします。', '{"options":["表面","場面","書面","正面"],"translation":"Hasil seleksi akan kami sampaikan di kemudian hari secara tertulis.","sentence_template":"審査の結果は、後日[blank]にてご連絡いたします。"}'::jsonb, '{"selected":"書面"}'::jsonb, '書面 (shomen) berarti ''dokumen tertulis'', sangat lazim dalam komunikasi resmi dan hukum.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi pengumuman resmi berikut: 理事長は今年度末の___に伴い、退任されることとなった。', '{"options":["中途採用","無期限延長","新規就任","任期満了"],"translation":"Ketua dewan pengurus akan mengundurkan diri seiring berakhirnya masa jabatan pada akhir tahun fiskal ini.","sentence_template":"理事長は今年度末の[blank]に伴い、退任されることとなった。"}'::jsonb, '{"selected":"任期満了"}'::jsonb, '任期満了 (ninki manryou) berarti ''berakhirnya masa jabatan secara penuh''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah hukum yang tepat: 改正された個人情報保護法は、来年四月一日に___される。', '{"options":["施行","旅行","流行","同行"],"translation":"Undang-undang perlindungan data pribadi yang telah direvisi akan mulai diberlakukan pada 1 April tahun depan.","sentence_template":"改正された個人情報保護法は、来年四月一日に[blank]される。"}'::jsonb, '{"selected":"施行"}'::jsonb, '施行 (shikou) berarti ''pemberlakuan resmi suatu undang-undang atau peraturan''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman penutupan acara berikut. Apa yang diumumkan oleh pembawa acara?', '{"audio_text":"以上をもちまして、本日の記念式典を滞りなく閉会とさせていただきます。","options":[{"id":"opt_1","text":"Acara peringatan hari ini resmi ditutup dengan lancar"},{"id":"opt_2","text":"Acara peringatan ditunda selama dua jam karena kendala teknis"},{"id":"opt_3","text":"Sesi tanya jawab baru akan dimulai setelah istirahat"},{"id":"opt_4","text":"Para tamu diminta pindah ke aula lantai dua"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '以上をもちまして...閉会とさせていただきます adalah kalimat penutup upacara formal yang baku.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pesan otomatis berikut. Kapan batas akhir penerimaan lamaran?', '{"audio_text":"本年度の奨学金申請は、今月三十日午後五時をもって受付を終了いたします。","options":[{"id":"opt_1","text":"Tanggal 13 bulan depan pukul lima sore"},{"id":"opt_2","text":"Tanggal 30 bulan ini pukul lima sore"},{"id":"opt_3","text":"Pendaftaran dibuka sepanjang tahun tanpa batas waktu"},{"id":"opt_4","text":"Tanggal 30 bulan ini pukul sembilan pagi"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '今月三十日午後五時をもって受付を終了いたします berarti ''pendaftaran ditutup pada tanggal 30 bulan ini pukul 17.00''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan menanggapi setiap keluhan pelanggan dengan penuh ketulusan."', '{"display_text":"お客様のご意見には、誠意をもって対応いたします。","romaji":"Okyakusama no go-iken ni wa, seii wo motte taiou itashimasu.","phonetic_breakdown":["o-kya-ku-sa-ma","no","go-i-ken","ni","wa","sei-i","wo","mo-tte","tai-ou","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"お客様のご意見には、誠意をもって対応いたします。"}'::jsonb, '誠意をもって (seii wo motte: dengan ketulusan/iktikad baik) adalah frasa standar layanan korporasi Jepang.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Pola ～をもって (Sarana & Batas)', 'Pola ～をもって', 'n1-u4-pola-utama', 'sparkle', 20, 2) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pengumuman resmi berikut: 本日___、旧バージョンのサポートを終了させていただきます。', '{"options":["にわたって","に沿って","をもって","をめぐって"],"translation":"Terhitung hari ini, kami mengakhiri dukungan untuk versi lama.","sentence_template":"本日[blank]、旧バージョンのサポートを終了させていただきます。"}'::jsonb, '{"selected":"をもって"}'::jsonb, 'Waktu + をもって menandai batas akhir atau titik waktu resmi suatu tindakan/pengumuman.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk menyatakan sarana/media resmi: 当選者の発表は、賞品の発送___代えさせていただきます。', '{"options":["をよそに","に際して","に至って","をもって"],"translation":"Pengumuman pemenang akan kami gantikan dengan pengiriman hadiah secara langsung.","sentence_template":"当選者の発表は、賞品の発送[blank]代えさせていただきます。"}'::jsonb, '{"selected":"をもって"}'::jsonb, '発送をもって代えさせていただきます adalah formula resmi yang sangat sering dipakai dalam pengumuman hasil undian/seleksi.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat sopan berikut: 以上___、私からの最終報告といたします。', '{"options":["を皮切りにして","を前提として","をもちまして","を余儀なくして"],"translation":"Dengan demikian, saya akhiri laporan akhir dari saya.","sentence_template":"以上[blank]、私からの最終報告といたします。"}'::jsonb, '{"selected":"をもちまして"}'::jsonb, 'をもちまして adalah bentuk super-sopan (teineigo) dari をもって untuk presentasi atau upacara resmi.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Hasil ujian akan diberitahukan melalui dokumen tertulis."', '{"tokens":["結果は","通知","書面","試験の","ながら","いたします","をもって","に至って"],"target_translation":"Hasil ujian akan diberitahukan melalui dokumen tertulis.","romaji":"Shiken no kekka wa shomen wo motte tsuuchi itashimasu."}'::jsonb, '["試験の","結果は","書面","をもって","通知","いたします"]'::jsonb, '書面をもって通知いたします berarti ''kami beritahukan melalui surat/dokumen tertulis''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dengan akhir bulan ini, toko tersebut akan menutup operasinya."', '{"tokens":["当店は","いたします","なりに","をめぐって","をもって","営業を","今月末","終了"],"target_translation":"Dengan akhir bulan ini, toko tersebut akan menutup operasinya.","romaji":"Kongetsumatsu wo motte touten wa eigyou wo shuuryou itashimasu."}'::jsonb, '["今月末","をもって","当店は","営業を","終了","いたします"]'::jsonb, '今月末をもって menandai akhir bulan ini sebagai batas resmi penutupan toko.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan melaksanakan tugas ini dengan penuh tanggung jawab."', '{"display_text":"強い責任感をもって、この任務を遂行いたします。","romaji":"Tsuyoi sekininkan wo motte, kono ninmu wo suikou itashimasu.","phonetic_breakdown":["tsu-yo-i","se-ki-nin-kan","wo","mo-tte","ko-no","nin-mu","wo","sui-kou","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"強い責任感をもって、この任務を遂行いたします。"}'::jsonb, '強い責任感をもって menyatakan sikap/semangat yang menyertai pelaksanaan tugas (遂行).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Surat Korporasi & Pengumuman', 'Dengar & Baca U4', 'n1-u4-dengar-baca', 'play-circle', 20, 3) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan berikut. Apa yang berubah mulai tanggal 31 Maret?', '{"audio_text":"誠に勝手ながら、三月三十一日をもちまして、電話によるお問い合わせ窓口を廃止させていただきます。","options":[{"id":"opt_1","text":"Jam layanan telepon diperpanjang menjadi 24 jam"},{"id":"opt_2","text":"Layanan pertanyaan via telepon ditiadakan per 31 Maret"},{"id":"opt_3","text":"Nomor telepon kantor pusat diganti dengan nomor bebas pulsa"},{"id":"opt_4","text":"Seluruh layanan daring ditutup sementara hingga akhir Maret"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '電話によるお問い合わせ窓口を廃止させていただきます berarti ''menghapus/menutup loket pertanyaan melalui telepon''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan pejabat berikut. Bagaimana keputusan pengadilan tersebut diterima?', '{"audio_text":"裁判所の判決を厳粛に受け止め、誠意をもって今後の対応に当たる所存です。","options":[{"id":"opt_1","text":"Menolak putusan pengadilan dan mengabaikan instruksinya"},{"id":"opt_2","text":"Meminta penundaan sidang hingga tahun depan"},{"id":"opt_3","text":"Menerima putusan dengan sungguh-sungguh dan menangani tindak lanjutnya dengan iktikad baik"},{"id":"opt_4","text":"Mengajukan tuntutan balik terhadap panitera pengadilan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '厳粛に受け止め (menerima dengan khidmat/sungguh-sungguh) dan 誠意をもって...に当たる (menangani dengan ketulusan).', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman universitas berikut. Bagaimana cara pendaftaran mata kuliah yang sah?', '{"audio_text":"履修登録は、所定のオンラインフォームの送信をもって完了とみなされます。","options":[{"id":"opt_1","text":"Dianggap selesai hanya dengan menghadiri kuliah pertama"},{"id":"opt_2","text":"Harus menyerahkan formulir kertas secara langsung ke dekan"},{"id":"opt_3","text":"Dilakukan secara otomatis tanpa perlu tindakan mahasiswa"},{"id":"opt_4","text":"Dianggap selesai setelah mengirimkan formulir daring yang ditentukan"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '送信をもって完了とみなされます berarti ''dianggap selesai dengan terkirimnya formulir tersebut''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi ketentuan kontrak berikut: 本契約は、双方の署名および捺印___発効するものとする。', '{"options":["なりに","とはいえ","をもって","を余儀なく"],"translation":"Kontrak ini mulai berlaku secara resmi dengan adanya tanda tangan dan cap dari kedua belah pihak.","sentence_template":"本契約は、双方の署名および捺印[blank]発効するものとする。"}'::jsonb, '{"selected":"をもって"}'::jsonb, '署名および捺印をもって発効する adalah frasa legal standar untuk syarat mulai berlakunya perjanjian.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk pernyataan pembukaan: ただいまの開会宣言___、国際シンポジウムを開始いたします。', '{"options":["に反しまして","をめぐりまして","をもちまして","に至りまして"],"translation":"Dengan deklarasi pembukaan barusan, simposium internasional resmi dimulai.","sentence_template":"ただいまの開会宣言[blank]、国際シンポジウムを開始いたします。"}'::jsonb, '{"selected":"をもちまして"}'::jsonb, '～をもちまして menandai titik dimulainya suatu acara resmi secara khidmat.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat formal berikut: 当社は、公正な取引と法令遵守___社会の信頼に応えてまいります。', '{"options":["をもって","に足らず","をよそに","ともなると"],"translation":"Perusahaan kami akan menjawab kepercayaan masyarakat melalui transaksi yang adil dan kepatuhan hukum.","sentence_template":"当社は、公正な取引と法令遵守[blank]社会の信頼に応えてまいります。"}'::jsonb, '{"selected":"をもって"}'::jsonb, '～をもって di sini bermakna ''dengan/melalui sarana (transaksi adil dan kepatuhan hukum)''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Bicara & Rakit Pernyataan Resmi', 'Bicara & Rakit U4', 'n1-u4-bicara-rakit', 'microphone', 20, 4) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan demikian, saya menutup presentasi hari ini."', '{"display_text":"以上をもちまして、本日の発表を終了させていただきます。","romaji":"Ijou wo mochimashite, honjitsu no happyou wo shuuryou sasete itadakimasu.","phonetic_breakdown":["i-jou","wo","mo-chi-ma-shi-te","hon-ji-tsu","no","ha-ppyou","wo","shuu-ryou","sa-se-te","i-ta-da-ki-ma-su"]}'::jsonb, '{"expected_transcript":"以上をもちまして、本日の発表を終了させていただきます。"}'::jsonb, 'Formula penutup presentasi paling formal dan berwibawa dalam bahasa Jepang bisnis.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pendaftaran ditutup pada pukul lima sore hari Jumat ini."', '{"display_text":"今週金曜日の午後五時をもって、応募を締め切ります。","romaji":"Konshuu kin''youbi no gogo goji wo motte, oubo wo shimekirimasu.","phonetic_breakdown":["kon-shuu","kin-you-bi","no","go-go","go-ji","wo","mo-tte","ou-bo","wo","shi-me-ki-ri-ma-su"]}'::jsonb, '{"expected_transcript":"今週金曜日の午後五時をもって、応募を締め切ります。"}'::jsonb, '締め切ります (menutup pendaftaran) sangat serasi dipasangkan dengan ～をもって.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan menyampaikan pemberitahuan resmi melalui situs web."', '{"display_text":"公式ウェブサイトでの掲載をもって、通知とさせていただきます。","romaji":"Koushiki webusaito de no keisai wo motte, tsuuchi to sasete itadakimasu.","phonetic_breakdown":["kou-shi-ki","we-bu-sai-to","de","no","kei-sai","wo","mo-tte","tsuu-chi","to","sa-se-te","i-ta-da-ki-ma-su"]}'::jsonb, '{"expected_transcript":"公式ウェブサイトでの掲載をもって、通知とさせていただきます。"}'::jsonb, '掲載をもって通知とする berarti ''pemuatan di situs resmi berlaku sebagai pemberitahuan sah''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Terhitung akhir tahun ini, beliau pensiun dari jabatannya."', '{"tokens":["される","とはいえ","をもって","退任","役職を","氏は","本年末","なりに"],"target_translation":"Terhitung akhir tahun ini, beliau pensiun dari jabatannya.","romaji":"Honnenmatsu wo motte shi wa yakushoku wo tainin sareru."}'::jsonb, '["本年末","をもって","氏は","役職を","退任","される"]'::jsonb, '本年末をもって (terhitung akhir tahun ini) diikuti bentuk hormat 退任される.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dengan pembayaran biaya, pendaftaran dianggap sah."', '{"tokens":["ばかりに","に至って","参加費の","登録完了","とみなす","ものとする","入金を","もって"],"target_translation":"Dengan pembayaran biaya, pendaftaran dianggap sah.","romaji":"Sankahi no nyuukin wo motte touroku kanryou to minasu mono to suru."}'::jsonb, '["参加費の","入金を","もって","登録完了","とみなす","ものとする"]'::jsonb, 'Kalimat klausul regulasi yang menggabungkan ～をもって dan ～ものとする.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kami akan menjawab harapan Anda dengan hasil nyata."', '{"tokens":["ながら","確かな","実績","皆様の","を余儀なく","ご期待に","をもって","お応えします"],"target_translation":"Kami akan menjawab harapan Anda dengan hasil nyata.","romaji":"Tashika na jisseki wo motte minasama no go-kitai ni okotae shimasu."}'::jsonb, '["確かな","実績","をもって","皆様の","ご期待に","お応えします"]'::jsonb, '確かな実績をもって berarti ''dengan rekam jejak/hasil yang nyata''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Tes Akhir Unit 4', 'Tes Akhir U4', 'n1-u4-tes-akhir', 'trophy', 25, 5) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk klausul resmi: 今回の改定案は、理事会の承認___正式に決定される。', '{"options":["とはいえ","なりに","に至って","をもって"],"translation":"Rancangan revisi kali ini akan diputuskan secara resmi dengan persetujuan dewan pengurus.","sentence_template":"今回の改定案は、理事会の承認[blank]正式に決定される。"}'::jsonb, '{"selected":"をもって"}'::jsonb, '理事会の承認をもって menandai sarana/syarat resmi penetapan keputusan.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pengumuman berikut: 誠に残念ですが、本日午後八時___、当館は閉館いたします。', '{"options":["に反しまして","をめぐりまして","をもちまして","を余儀なくして"],"translation":"Sungguh sangat disayangkan, terhitung hari ini pukul delapan malam, gedung ini akan ditutup secara permanen.","sentence_template":"誠に残念ですが、本日午後八時[blank]、当館は閉館いたします。"}'::jsonb, '{"selected":"をもちまして"}'::jsonb, '本日午後八時をもちまして adalah ungkapan penutupan resmi yang sangat santun.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pemberitahuan resmi berikut. Kapan peraturan baru tersebut mulai berlaku?', '{"audio_text":"新たな就業規則は、来月一日をもって施行されますので、全社員は事前に内容を確認してください。","options":[{"id":"opt_1","text":"Mulai tanggal 1 bulan depan"},{"id":"opt_2","text":"Mulai hari ini juga tanpa pemberitahuan sebelumnya"},{"id":"opt_3","text":"Mulai akhir tahun depan"},{"id":"opt_4","text":"Hanya berlaku bagi karyawan baru yang bergabung bulan lalu"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '来月一日をもって施行されます berarti ''diberlakukan mulai tanggal 1 bulan depan''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kutipan pidato berikut. Apa sikap yang dijanjikan oleh pembicara?', '{"audio_text":"今後も社員一丸となり、万全の体制をもってサービスの品質向上に努めてまいります。","options":[{"id":"opt_1","text":"Mengurangi jumlah staf layanan pelanggan"},{"id":"opt_2","text":"Berupaya meningkatkan mutu layanan dengan sistem kesiapan yang paripurna"},{"id":"opt_3","text":"Menyerahkan seluruh operasional kepada pihak ketiga"},{"id":"opt_4","text":"Menghentikan pengembangan produk baru sementara waktu"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '万全の体制をもって (dengan sistem kesiapan penuh) meningkatkan kualitas layanan.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Pemberitahuan tertulis ini berlaku sebagai undangan resmi."', '{"tokens":["正式な","に至って","とはいえ","ご案内","をもって","といたします","本書の","送付"],"target_translation":"Pemberitahuan tertulis ini berlaku sebagai undangan resmi.","romaji":"Honsho no soufu wo motte seishiki na go-annai to itashimasu."}'::jsonb, '["本書の","送付","をもって","正式な","ご案内","といたします"]'::jsonb, '本書の送付をもってご案内といたします adalah kalimat penutup surat resmi korporasi.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami menyambut para tamu undangan dengan penuh rasa hormat."', '{"display_text":"深い敬意をもって、ご来賓の皆様をお迎えいたします。","romaji":"Fukai keii wo motte, go-raihin no minasama wo omukae itashimasu.","phonetic_breakdown":["fu-kai","kei-i","wo","mo-tte","go-rai-hin","no","mi-na-sa-ma","wo","o-mu-ka-e","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"深い敬意をもって、ご来賓の皆様をお迎えいたします。"}'::jsonb, '深い敬意をもって (dengan rasa hormat yang mendalam) adalah ungkapan seremonial tingkat N1.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index) VALUES (v_level_id, 'Tingkat Ekstrem Tanpa Tandingan (～極まりない)', 'Ekspresikan penilaian tajam, kecaman diplomatis, kritik etika publik, dan apresiasi formal pada tingkat tertinggi.', 'curriculum', 5) RETURNING id INTO v_unit_id;
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kosakata Kritik & Etika Publik', 'Kosakata Kritik', 'n1-u5-kosakata', 'shield-check', 15, 1) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah diplomatis yang tepat: 合意に反する一方的な行動は、誠に___である。', '{"options":["満足","愉快","歓迎","遺憾"],"translation":"Tindakan sepihak yang melanggar kesepakatan sungguh sangat disayangkan.","sentence_template":"合意に反する一方的な行動は、誠に[blank]である。"}'::jsonb, '{"selected":"遺憾"}'::jsonb, '遺憾 (ikan) adalah istilah diplomatis dan resmi untuk menyatakan penyesalan keras atau ketidaksetujuan.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kritik sosial berikut: 公共の場でのマナーを無視した行為は___だと言わざるを得ない。', '{"options":["合理的","模範的","非常識","建設的"],"translation":"Perilaku yang mengabaikan tata krama di tempat umum mau tidak mau harus disebut tidak tahu adat.","sentence_template":"公共の場でのマナーを無視した行為は[blank]だと言わざるを得ない。"}'::jsonb, '{"selected":"非常識"}'::jsonb, '非常識 (hijoushiki) berarti ''melampaui akal sehat / tidak beradab / tidak tahu aturan umum''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk penilaian pernyataan resmi: 責任の所在を曖昧にしたままの説明は、___な印象を与える。', '{"options":["誠実","明快","無責任","丁寧"],"translation":"Penjelasan yang membiarkan letak tanggung jawab tetap kabur memberikan kesan sangat tidak bertanggung jawab.","sentence_template":"責任の所在を曖昧にしたままの説明は、[blank]な印象を与える。"}'::jsonb, '{"selected":"無責任"}'::jsonb, '無責任 (musekinin) berarti ''tidak bertanggung jawab'', sering muncul dalam kritik politik dan bisnis.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan juru bicara kementerian berikut. Bagaimana sikap pemerintah terhadap tindakan tersebut?', '{"audio_text":"事前の協議もなく規制を強化した相手国の対応は、極めて不適切であり、強く抗議する。","options":[{"id":"opt_1","text":"Mendukung penuh keputusan negara mitra"},{"id":"opt_2","text":"Menilai tindakan tersebut sangat tidak pantas dan melayangkan protes keras"},{"id":"opt_3","text":"Meminta waktu satu bulan untuk mempelajari isi aturan"},{"id":"opt_4","text":"Mengucapkan terima kasih atas konsultasi sebelumnya"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '極めて不適切であり、強く抗議する berarti ''sangat tidak patut dan memprotes keras''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan komentar editor berikut. Apa pujian yang diberikan kepada laporan tersebut?', '{"audio_text":"膨大なデータを整理し、要点を簡潔にまとめた彼の報告書は実に明快だ。","options":[{"id":"opt_1","text":"Laporannya terlalu panjang dan bertele-tele"},{"id":"opt_2","text":"Datanya tidak lengkap sehingga sulit dipahami"},{"id":"opt_3","text":"Laporannya sangat jelas, ringkas, dan berhasil merangkum data besar"},{"id":"opt_4","text":"Laporannya harus ditulis ulang oleh tim lain"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '要点を簡潔にまとめた...実に明快だ berarti ''merangkum poin inti secara ringkas dan sungguh sangat jelas''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pernyataan seperti itu sungguh tidak sopan terhadap para hadirin."', '{"display_text":"そのような発言は、出席者に対して大変失礼にあたる。","romaji":"Sono you na hatsugen wa, shussekisha ni taishite taihen shitsurei ni ataru.","phonetic_breakdown":["so-no","you","na","ha-tsu-gen","wa","shu-sse-ki-sha","ni","tai-shi-te","tai-hen","shi-tsu-rei","ni","a-ta-ru"]}'::jsonb, '{"expected_transcript":"そのような発言は、出席者に対して大変失礼にあたる。"}'::jsonb, '失礼にあたる berarti ''termasuk tindakan yang tidak sopan'' dalam konteks formal.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Pola ～極まりない & ～極まる', 'Pola ～極まりない', 'n1-u5-pola-utama', 'sparkle', 20, 2) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat kritik berikut: 十分な安全確認を怠ったまま運行を続けるのは、危険___。', '{"options":["とはいえ","に足りない","余儀ない","極まりない"],"translation":"Melanjutkan operasional tanpa pemeriksaan keselamatan yang memadai adalah hal yang luar biasa berbahaya.","sentence_template":"十分な安全確認を怠ったまま運行を続けるのは、危険[blank]。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, 'Kata sifat-na (akar) + 極まりない menyatakan tingkat ekstrem ''tiada tara / luar biasa''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk memodifikasi kata benda: 事実確認をせずに報道するとは、無責任___行為である。', '{"options":["に至る","に足る","極まる","をめぐる"],"translation":"Memberitakan tanpa verifikasi fakta adalah tindakan yang luar biasa tidak bertanggung jawab.","sentence_template":"事実確認をせずに報道するとは、無責任[blank]行為である。"}'::jsonb, '{"selected":"極まる"}'::jsonb, '～極まる (atau ～極まりない) dapat diletakkan sebelum kata benda untuk menekankan derajat ekstrem.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pernyataan resmi berikut: このような不祥事が再び起きたことは、遺憾___。', '{"options":["の限りである","の極みである","の余地がある","の至りである"],"translation":"Terulangnya skandal semacam ini sungguh sangat disayangkan hingga tiada tara.","sentence_template":"このような不祥事が再び起きたことは、遺憾[blank]。"}'::jsonb, '{"selected":"の極みである"}'::jsonb, '遺憾の極みである (puncak penyesalan) adalah varian nomina dari 遺憾極まりない yang sangat formal.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sikapnya terhadap para pelanggan sungguh luar biasa tidak sopan."', '{"tokens":["失礼","彼の","なりに","態度は","極まりない","顧客に","に足る","対する"],"target_translation":"Sikapnya terhadap para pelanggan sungguh luar biasa tidak sopan.","romaji":"Kare no kokyaku ni taisuru taido wa shitsurei kiwamarinai."}'::jsonb, '["彼の","顧客に","対する","態度は","失礼","極まりない"]'::jsonb, '失礼極まりない berarti ''luar biasa tidak sopan / sangat kurang ajar''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Keputusan yang mengabaikan pendapat lapangan itu sangat tidak menyenangkan."', '{"tokens":["極まりない","無視した","決定には","現場を","思いだ","不愉快","をもって","ながら"],"target_translation":"Keputusan yang mengabaikan pendapat lapangan itu sangat tidak menyenangkan.","romaji":"Genba wo mushi shita kettei ni wa fuyukai kiwamarinai omoi da."}'::jsonb, '["現場を","無視した","決定には","不愉快","極まりない","思いだ"]'::jsonb, '不愉快極まりない思い berarti ''perasaan yang luar biasa tidak menyenangkan''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tindakan yang merugikan banyak pihak itu sungguh sangat tidak tahu aturan."', '{"display_text":"周囲に多大な迷惑をかける行為は、非常識極まりない。","romaji":"Shuui ni tadai na meiwaku wo kakeru koui wa, hijoushiki kiwamarinai.","phonetic_breakdown":["shuu-i","ni","ta-dai","na","mei-wa-ku","wo","ka-ke-ru","kou-i","wa","hi-jou-shi-ki","ki-wa-ma-ri-nai"]}'::jsonb, '{"expected_transcript":"周囲に多大な迷惑をかける行為は、非常識極まりない。"}'::jsonb, '多大な迷惑 (gangguan yang sangat besar) dikritik keras dengan 非常識極まりない.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kecaman Tajuk & Apresiasi Formal', 'Dengar & Baca U5', 'n1-u5-dengar-baca', 'play-circle', 20, 3) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan komentar kritikus berikut. Apa penilaiannya terhadap rencana pembangunan tersebut?', '{"audio_text":"環境への影響を十分に調査せず着工に踏み切るのは、あまりにも無謀極まりない判断だ。","options":[{"id":"opt_1","text":"Keputusan yang sangat gegabah karena memulai konstruksi tanpa kajian lingkungan memadai"},{"id":"opt_2","text":"Keputusan yang sangat bijaksana dan ramah lingkungan"},{"id":"opt_3","text":"Proyek tersebut sudah selesai dikerjakan lebih cepat dari jadwal"},{"id":"opt_4","text":"Kajian lingkungan telah disetujui oleh seluruh warga setempat"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '無謀極まりない判断 berarti ''keputusan yang luar biasa nekat/gegabah''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan kutipan pidato penerimaan penghargaan berikut. Bagaimana perasaan pembicara?', '{"audio_text":"このような栄誉ある賞をいただき、身に余る光栄であり、感激極まりない思いでございます。","options":[{"id":"opt_1","text":"Merasa kecewa karena hadiahnya tidak sesuai harapan"},{"id":"opt_2","text":"Merasa ragu apakah penghargaan tersebut sah"},{"id":"opt_3","text":"Merasa sangat terhormat dan luar biasa terharu"},{"id":"opt_4","text":"Menolak menerima penghargaan karena alasan pribadi"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '感激極まりない思い menunjukkan rasa haru yang mendalam (penggunaan positif dari ～極まりない).', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan tanggapan warga terhadap gangguan di fasilitas umum. Apa yang dikeluhkan?', '{"audio_text":"深夜に大音量で音楽を流し続けるとは、近隣住民にとって迷惑極まりない行為だ。","options":[{"id":"opt_1","text":"Lampu jalan di lingkungan tersebut padam setiap malam"},{"id":"opt_2","text":"Taman kota ditutup terlalu awal pada hari Minggu"},{"id":"opt_3","text":"Pengumpulan sampah terlambat satu hari"},{"id":"opt_4","text":"Memutar musik keras tengah malam sangat mengganggu warga sekitar"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '迷惑極まりない行為 berarti ''tindakan yang luar biasa mengganggu''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi teks editorial berikut: 説明責任を果たさず批判を避け続ける姿勢は、不誠実___。', '{"options":["極まりない","とはいえ","を余儀なくされる","に至らない"],"translation":"Sikap terus menghindari kritik tanpa memenuhi kewajiban penjelasan sungguh luar biasa tidak tulus.","sentence_template":"説明責任を果たさず批判を避け続ける姿勢は、不誠実[blank]。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, '不誠実極まりない adalah kritik tajam dalam tajuk rencana surat kabar Jepang.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata yang paling tepat sebelum 極まりない: 書類手続きが___極まりなく、利用者の負担が大きい。', '{"options":["円滑","快適","迅速","煩雑"],"translation":"Prosedur dokumennya luar biasa berbelit-belit, sehingga beban pengguna sangat besar.","sentence_template":"書類手続きが[blank]極まりなく、利用者の負担が大きい。"}'::jsonb, '{"selected":"煩雑"}'::jsonb, '煩雑 (hanzatsu: rumit/berbelit-belit) + 極まりなく sangat alami untuk mengkritik birokrasi.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat pujian formal berikut: 彼の論文は論理構成が___極まりなく、専門家の間でも高く評価された。', '{"options":["精緻","曖昧","冗長","粗雑"],"translation":"Struktur logika makalahnya luar biasa tajam dan terperinci, sehingga dinilai tinggi di kalangan pakar.","sentence_template":"彼の論文は論理構成が[blank]極まりなく、専門家の間でも高く評価された。"}'::jsonb, '{"selected":"精緻"}'::jsonb, '精緻 (seichi: sangat teliti/halus/presisi) berpasangan positif dengan 極まりなく.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Bicara & Rakit Kritik Tajam', 'Bicara & Rakit U5', 'n1-u5-bicara-rakit', 'microphone', 20, 4) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menyebarkan informasi yang belum terverifikasi adalah hal yang sangat berbahaya."', '{"display_text":"未確認の情報を拡散するのは、危険極まりない行為だ。","romaji":"Mikakunin no jouhou wo kakusan suru no wa, kiken kiwamarinai koui da.","phonetic_breakdown":["mi-ka-ku-nin","no","jou-hou","wo","ka-ku-san","su-ru","no","wa","ki-ken","ki-wa-ma-ri-nai","kou-i","da"]}'::jsonb, '{"expected_transcript":"未確認の情報を拡散するのは、危険極まりない行為だ。"}'::jsonb, '未確認の情報 (informasi belum terkonfirmasi) dan 危険極まりない行為 (tindakan amat berbahaya).', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Batal mendadak tanpa pemberitahuan sungguh luar biasa tidak sopan."', '{"display_text":"連絡もなく直前にキャンセルするとは、失礼極まりない。","romaji":"Renraku mo naku chokuzen ni kyanseru suru to wa, shitsurei kiwamarinai.","phonetic_breakdown":["ren-ra-ku","mo","na-ku","cho-ku-zen","ni","kyan-se-ru","su-ru","to","wa","shi-tsu-rei","ki-wa-ma-ri-nai"]}'::jsonb, '{"expected_transcript":"連絡もなく直前にキャンセルするとは、失礼極まりない。"}'::jsonb, 'Pola ～とは、...極まりない sering digunakan untuk mengekspresikan keterkejutan sekaligus kecaman.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kemenangan dramatis itu sungguh luar biasa memuaskan."', '{"display_text":"あの劇的な逆転勝利は、痛快極まりない瞬間だった。","romaji":"Ano gekiteki na gyakuten shouri wa, tsuukai kiwamarinai shunkan datta.","phonetic_breakdown":["a-no","ge-ki-te-ki","na","gya-ku-ten","shou-ri","wa","tsuu-kai","ki-wa-ma-ri-nai","shun-kan","da-tta"]}'::jsonb, '{"expected_transcript":"あの劇的な逆転勝利は、痛快極まりない瞬間だった。"}'::jsonb, '痛快極まりない (luar biasa seru/memuaskan) adalah contoh penggunaan positif yang kuat.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Memalsukan data penelitian adalah pelanggaran etika yang luar biasa tidak bertanggung jawab."', '{"tokens":["をもって","無責任","なりに","不正行為","極まりない","改ざんは","である","研究データの"],"target_translation":"Memalsukan data penelitian adalah pelanggaran etika yang luar biasa tidak bertanggung jawab.","romaji":"Kenkyuu deeta no kaizan wa musekinin kiwamarinai fusei koui de aru."}'::jsonb, '["研究データの","改ざんは","無責任","極まりない","不正行為","である"]'::jsonb, '改ざん (pemalsuan) dan 不正行為 (tindakan curang/pelanggaran).', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Penjelasan yang tidak konsisten itu sungguh sangat membingungkan."', '{"tokens":["ない","説明は","極まりない","とはいえ","ものだ","不可解","一貫性の","に至って"],"target_translation":"Penjelasan yang tidak konsisten itu sungguh sangat membingungkan.","romaji":"Ikkansei no nai setsumei wa fukakai kiwamarinai mono da."}'::jsonb, '["一貫性の","ない","説明は","不可解","極まりない","ものだ"]'::jsonb, '不可解極まりない berarti ''luar biasa sulit dimengerti / sangat janggal''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meremehkan standar keselamatan adalah kelalaian yang amat berbahaya."', '{"tokens":["安全基準を","に足る","軽視する","ながら","態度は","極まる","危険","ものだ"],"target_translation":"Meremehkan standar keselamatan adalah kelalaian yang amat berbahaya.","romaji":"Anzen kijun wo keishi suru taido wa kiken kiwamaru mono da."}'::jsonb, '["安全基準を","軽視する","態度は","危険","極まる","ものだ"]'::jsonb, '危険極まるものだ menekankan tingkat bahaya yang sudah melampaui batas.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Tes Akhir Unit 5', 'Tes Akhir U5', 'n1-u5-tes-akhir', 'trophy', 25, 5) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 顧客の個人情報を杜撰に管理していたとは、言語道断であり遺憾___。', '{"options":["に足らない","を余儀なくされた","極まりない","とはいえ"],"translation":"Mengelola data pribadi pelanggan secara sembrono sungguh keterlaluan dan amat sangat disayangkan.","sentence_template":"顧客の個人情報を杜撰に管理していたとは、言語道断であり遺憾[blank]。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, '遺憾極まりない menutup kecaman formal dengan penekanan tingkat tertinggi.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 根拠のない誹謗中傷を繰り返す行為は、悪質___ものである。', '{"options":["に至る","に足る","極まる","をもって"],"translation":"Tindakan mengulang fitnah tanpa dasar adalah perbuatan yang luar biasa jahat.","sentence_template":"根拠のない誹謗中傷を繰り返す行為は、悪質[blank]ものである。"}'::jsonb, '{"selected":"極まる"}'::jsonb, '悪質極まるもの berarti ''sesuatu yang tingkat kejahatan/keburukannya ekstrem''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kutipan komentar berikut. Mengapa pembicara mengecam usulan tersebut?', '{"audio_text":"住民への説明会を一度も開かずに計画を強行するとは、独善的極まりないやり方だ。","options":[{"id":"opt_1","text":"Karena pertemuan warga diadakan terlalu sering setiap minggu"},{"id":"opt_2","text":"Karena memaksakan proyek tanpa sekali pun mengadakan sosialisasi dinilai sangat egois dan sepihak"},{"id":"opt_3","text":"Karena anggaran proyek tersebut terlalu kecil"},{"id":"opt_4","text":"Karena rencana tersebut dibatalkan secara mendadak"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '独善的極まりない berarti ''luar biasa merasa benar sendiri / sepihak''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan perjalanan berikut. Bagaimana kesan pembicara terhadap layanan penginapan itu?', '{"audio_text":"細部まで行き届いたおもてなしは実に快適極まりなく、忘れられない滞在となった。","options":[{"id":"opt_1","text":"Sangat kecewa dengan kebersihan kamar"},{"id":"opt_2","text":"Harganya terlalu mahal dibandingkan fasilitasnya"},{"id":"opt_3","text":"Keramahtamahan yang teliti hingga detail membuat masa inap sangat nyaman dan tak terlupakan"},{"id":"opt_4","text":"Lokasinya terlalu jauh dari stasiun kereta"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '快適極まりなく berarti ''luar biasa nyaman''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Membiarkan kerusakan jembatan tanpa perbaikan adalah tindakan yang amat berbahaya."', '{"tokens":["放置する","をもって","危険","極まりない","なりに","損傷を","橋の","のは"],"target_translation":"Membiarkan kerusakan jembatan tanpa perbaikan adalah tindakan yang amat berbahaya.","romaji":"Hashi no sonshou wo houchi suru no wa kiken kiwamarinai."}'::jsonb, '["橋の","損傷を","放置する","のは","危険","極まりない"]'::jsonb, '損傷を放置する (membiarkan kerusakan terbengkalai) dinilai 危険極まりない.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sungguh luar biasa tidak adil jika hanya satu pihak yang menanggung semua kerugian."', '{"display_text":"一方だけに全ての損失を押し付けるのは、不公平極まりない。","romaji":"Ippou dake ni subete no sonshitsu wo oshitsukeru no wa, fukouhei kiwamarinai.","phonetic_breakdown":["i-ppou","da-ke","ni","su-be-te","no","son-shi-tsu","wo","o-shi-tsu-ke-ru","no","wa","fu-kou-hei","ki-wa-ma-ri-nai"]}'::jsonb, '{"expected_transcript":"一方だけに全ての損失を押し付けるのは、不公平極まりない。"}'::jsonb, '不公平極まりない berarti ''luar biasa tidak adil''.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index) VALUES (v_level_id, 'Dengan Caranya Sendiri (～なりに)', 'Sampaikan refleksi diri, empati kepemimpinan, dan penghargaan atas kontribusi sesuai kapasitas serta peran masing-masing.', 'curriculum', 6) RETURNING id INTO v_unit_id;
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kosakata Refleksi & Kepemimpinan', 'Kosakata Refleksi', 'n1-u6-kosakata', 'users-three', 15, 1) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk kalimat refleksi berikut: 正解のない課題に対して、チーム全員で解決策を___し続けている。', '{"options":["拒絶","断定","放棄","模索"],"translation":"Terhadap tantangan tanpa jawaban pasti, seluruh tim terus mencari-cari jalan keluar.","sentence_template":"正解のない課題に対して、チーム全員で解決策を[blank]し続けている。"}'::jsonb, '{"selected":"模索"}'::jsonb, '模索 (mosaku) berarti ''meraba-raba / terus mencari jalan keluar di tengah ketidakpastian''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat manajemen berikut: 限られた資源の中でも、現場の___によって業務が大きく改善された。', '{"options":["現状維持","形式主義","創意工夫","責任転嫁"],"translation":"Meski sumber daya terbatas, berkat kreativitas dan inisiatif tim lapangan, operasional meningkat pesat.","sentence_template":"限られた資源の中でも、現場の[blank]によって業務が大きく改善された。"}'::jsonb, '{"selected":"創意工夫"}'::jsonb, '創意工夫 (soui kufuu) berarti ''daya cipta dan siasat kreatif'' untuk mengatasi keterbatasan.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat untuk menggambarkan dilema batin: 理想と現実の間で深い___を抱えながら、彼は決断を下した。', '{"options":["満足","安心","油断","葛藤"],"translation":"Sambil memendam konflik batin yang dalam antara idealisme dan realitas, ia mengambil keputusan.","sentence_template":"理想と現実の間で深い[blank]を抱えながら、彼は決断を下した。"}'::jsonb, '{"selected":"葛藤"}'::jsonb, '葛藤 (kattou) berarti ''konflik batin / pergulatan pikiran''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan manajer berikut. Sikap apa yang dihargai oleh pembicara?', '{"audio_text":"経験の浅い若手であっても、日々の業務に誠実に向き合い、周囲への配慮を忘れない姿勢は高く評価される。","options":[{"id":"opt_1","text":"Hanya bekerja cepat tanpa memedulikan rekan kerja"},{"id":"opt_2","text":"Menghadapi pekerjaan dengan tulus dan tidak lupa bertenggang rasa terhadap sekitar"},{"id":"opt_3","text":"Menghindari tugas sulit sampai memiliki pengalaman sepuluh tahun"},{"id":"opt_4","text":"Selalu bekerja lembur hingga larut malam setiap hari"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '誠実に向き合い (menghadapi dengan tulus) dan 周囲への配慮 (perhatian/tenggang rasa pada sekitar).', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan refleksi pemimpin tim berikut. Bagaimana ia memandang peran setiap anggota?', '{"audio_text":"全員が同じ能力を持つ必要はなく、それぞれの持ち味を生かして組織に貢献することが大切だ。","options":[{"id":"opt_1","text":"Semua anggota harus memiliki keahlian yang persis sama"},{"id":"opt_2","text":"Hanya pemimpin yang bertanggung jawab atas kontribusi tim"},{"id":"opt_3","text":"Penting bagi tiap anggota berkontribusi dengan memanfaatkan keunggulan khas masing-masing"},{"id":"opt_4","text":"Anggota baru tidak perlu menyampaikan pendapat dalam rapat"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '持ち味を生かして組織に貢献する berarti ''memanfaatkan ciri khas/keunggulan diri untuk berkontribusi pada organisasi''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saling menghormati posisi masing-masing adalah fondasi kerja sama."', '{"display_text":"互いの立場を尊重し合うことが、信頼関係の基盤となる。","romaji":"Tagai no tachiba wo sonchou shiau koto ga, shinrai kankei no kiban to naru.","phonetic_breakdown":["ta-gai","no","ta-chi-ba","wo","son-chou","shi-a-u","ko-to","ga","shin-rai","kan-kei","no","ki-ban","to","na-ru"]}'::jsonb, '{"expected_transcript":"互いの立場を尊重し合うことが、信頼関係の基盤となる。"}'::jsonb, '立場を尊重し合う (saling menghormati posisi/sudut pandang) adalah ungkapan kepemimpinan yang matang.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Pola ～なりに & ～なりの', 'Pola ～なりに', 'n1-u6-pola-utama', 'sparkle', 20, 2) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat refleksi berikut: 新人として未熟な点も多いが、今は私___最善を尽くしている。', '{"options":["なりに","をもって","に至って","極まりなく"],"translation":"Sebagai pendatang baru masih banyak kekurangan, tetapi sekarang saya berusaha semaksimal mungkin dengan cara saya sendiri.","sentence_template":"新人として未熟な点も多いが、今は私[blank]最善を尽くしている。"}'::jsonb, '{"selected":"なりに"}'::jsonb, 'Kata benda + なりに menyatakan ''sesuai dengan kapasitas/posisi/caranya sendiri''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat sebelum kata benda: 子どもたちにも、子ども___悩みや葛藤があるものだ。', '{"options":["なりの","なりに","ながらの","ならではの"],"translation":"Anak-anak pun memiliki kekhawatiran dan pergulatan batin tersendiri sesuai dunia anak-anak.","sentence_template":"子どもたちにも、子ども[blank]悩みや葛藤があるものだ。"}'::jsonb, '{"selected":"なりの"}'::jsonb, 'Ketika memodifikasi kata benda (悩みや葛藤), gunakan bentuk ～なりの.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan pola yang benar: 収入が限られているのだから、今の生活水準___やりくりするしかない。', '{"options":["なりに","をよそに","に足らず","とはいえ"],"translation":"Karena penghasilan terbatas, tidak ada pilihan selain mengatur keuangan sesuai standar hidup sekarang.","sentence_template":"収入が限られているのだから、今の生活水準[blank]やりくりするしかない。"}'::jsonb, '{"selected":"なりに"}'::jsonb, '生活水準なりに berarti ''sesuai dengan tingkat/standar kehidupan saat ini''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dia pun berusaha memikirkan masa depan tim dengan caranya sendiri."', '{"tokens":["彼","考えている","チームの","将来を","彼も","なりに","をもって","極まりない"],"target_translation":"Dia pun berusaha memikirkan masa depan tim dengan caranya sendiri.","romaji":"Kare mo kare nari ni chiimu no shourai wo kangaete iru."}'::jsonb, '["彼も","彼","なりに","チームの","将来を","考えている"]'::jsonb, 'Pengulangan 彼も彼なりに sangat idiomatis untuk menunjukkan empati bahwa dia pun berusaha sesuai kapasitasnya.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Perusahaan kecil memiliki keunggulan tersendiri yang sesuai skalanya."', '{"tokens":["なりの","ある","ながら","中小企業には","中小企業","に至って","ものだ","強みが"],"target_translation":"Perusahaan kecil memiliki keunggulan tersendiri yang sesuai skalanya.","romaji":"Chuushou kigyou ni wa chuushou kigyou nari no tsuyomi ga aru mono da."}'::jsonb, '["中小企業には","中小企業","なりの","強みが","ある","ものだ"]'::jsonb, 'XにはXなりのYがある berarti ''X memiliki Y tersendiri yang sesuai dengan sifat/skalanya''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya telah menyusun usulan ini sesuai kemampuan saya sendiri."', '{"display_text":"不十分な点もありますが、自分なりに提案をまとめてみました。","romaji":"Fujuubun na ten mo arimasu ga, jibun nari ni teian wo matomete mimashita.","phonetic_breakdown":["fu-juu-bun","na","ten","mo","a-ri-ma-su","ga","ji-bun","na-ri","ni","tei-an","wo","ma-to-me-te","mi-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"不十分な点もありますが、自分なりに提案をまとめてみました。"}'::jsonb, '自分なりに (dengan cara/kapasitas saya sendiri) bernuansa rendah hati namun sungguh-sungguh dalam rapat bisnis.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Wacana Empati & Pengelolaan Tim', 'Dengar & Baca U6', 'n1-u6-dengar-baca', 'play-circle', 20, 3) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pendapat seorang direktur berikut. Apa pandangannya tentang gaya kepemimpinan?', '{"audio_text":"部下のやり方が自分の理想と違っても、相手なりに考えた工夫をまず認めることが大切だ。","options":[{"id":"opt_1","text":"Bawahan wajib meniru persis cara kerja atasan tanpa modifikasi"},{"id":"opt_2","text":"Penting untuk terlebih dahulu menghargai inisiatif bawahan sesuai pemikirannya"},{"id":"opt_3","text":"Atasan sebaiknya mengerjakan semua tugas sendiri"},{"id":"opt_4","text":"Perbedaan cara kerja harus langsung diberi sanksi"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '相手なりに考えた工夫をまず認める berarti ''menghargai dulu siasat/upaya yang dipikirkan lawan bicara sesuai kapasitasnya''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan wawancara penulis berikut. Bagaimana ia menilai karya debutnya?', '{"audio_text":"今読み返すと未熟な表現も多いが、当時の私なりの精一杯の情熱が込められている。","options":[{"id":"opt_1","text":"Ia ingin menghapus karya debutnya karena tidak ada nilai sama sekali"},{"id":"opt_2","text":"Ia merasa gaya bahasanya dulu jauh lebih sempurna daripada sekarang"},{"id":"opt_3","text":"Meski banyak ungkapan belum matang, karya itu memuat semangat maksimalnya saat itu"},{"id":"opt_4","text":"Karya debutnya ditulis sepenuhnya oleh editornya"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '当時の私なりの精一杯の情熱 berarti ''semangat sepenuh hati sesuai kapasitas saya pada masa itu''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan tentang kehidupan daerah. Apa keunggulan kota kecil menurut pembicara?', '{"audio_text":"大都市のような派手さはないが、地方都市には地方都市なりの豊かな暮らし方がある。","options":[{"id":"opt_1","text":"Kota daerah memiliki cara hidup yang kaya tersendiri meski tidak semegah kota besar"},{"id":"opt_2","text":"Kota daerah jauh lebih ramai dan bising daripada ibu kota"},{"id":"opt_3","text":"Tidak ada keuntungan apa pun tinggal di kota daerah"},{"id":"opt_4","text":"Biaya hidup di kota daerah jauh lebih mahal daripada di Tokyo"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '地方都市には地方都市なりの豊かな暮らし方がある menunjukkan apresiasi yang proporsional.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi refleksi karier berikut: 若手には若手___役割があり、ベテランとは違う視点で組織を活性化できる。', '{"options":["極まりの","に至っての","をもっての","なりの"],"translation":"Karyawan muda memiliki perannya sendiri yang sesuai, dan dapat menghidupkan organisasi dari sudut pandang berbeda dari senior.","sentence_template":"若手には若手[blank]役割があり、ベテランとは違う視点で組織を活性化できる。"}'::jsonb, '{"selected":"なりの"}'::jsonb, '若手なりの役割 berarti ''peran tersendiri yang sesuai dengan posisi karyawan muda''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat: 完璧な語学力ではなくても、相手と分かり合おうと自分___努力する姿勢が伝わる。', '{"options":["を余儀なく","なりに","に足る","とはいえ"],"translation":"Meskipun kemampuan bahasanya belum sempurna, sikap berusaha dengan cara sendiri untuk saling memahami akan tersampaikan.","sentence_template":"完璧な語学力ではなくても、相手と分かり合おうと自分[blank]努力する姿勢が伝わる。"}'::jsonb, '{"selected":"なりに"}'::jsonb, '自分なりに努力する姿勢 (sikap berusaha sesuai kemampuan diri sendiri).', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予算が少ないなら少ない___、最大限の効果を出せる企画を練ろう。', '{"options":["に至って","いかんによらず","をもって","なりに"],"translation":"Jika anggarannya memang sedikit, mari susun rencana yang bisa menghasilkan dampak maksimal sesuai keterbatasan itu.","sentence_template":"予算が少ないなら少ない[blank]、最大限の効果を出せる企画を練ろう。"}'::jsonb, '{"selected":"なりに"}'::jsonb, 'Pola AならAなりに (kalau memang A, ya sesuai kondisi A itu) sangat sering diujikan di JLPT N1.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Bicara & Rakit Refleksi Diri', 'Bicara & Rakit U6', 'n1-u6-bicara-rakit', 'microphone', 20, 4) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika waktunya sempit, mari kita susun prioritas sesuai kondisi itu."', '{"display_text":"時間が限られているなら限られているなりに、優先順位を明確にしよう。","romaji":"Jikan ga kagirarete iru nara kagirarete iru nari ni, yuusen jun''i wo meikaku ni shiyou.","phonetic_breakdown":["ji-kan","ga","ka-gi-ra-re-te","i-ru","na-ra","ka-gi-ra-re-te","i-ru","na-ri","ni","yuu-sen","jun-i","wo","mei-ka-ku","ni","shi-you"]}'::jsonb, '{"expected_transcript":"時間が限られているなら限られているなりに、優先順位を明確にしよう。"}'::jsonb, 'Pola ～なら～なりに menegaskan sikap adaptif dan solutif di tengah keterbatasan.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setiap generasi memiliki nilai dan cara pandangnya sendiri."', '{"display_text":"それぞれの世代には、それぞれの世代なりの価値観がある。","romaji":"Sorezore no sedai ni wa, sorezore no sedai nari no kachikan ga aru.","phonetic_breakdown":["so-re-zo-re","no","se-dai","ni","wa","so-re-zo-re","no","se-dai","na-ri","no","ka-chi-kan","ga","a-ru"]}'::jsonb, '{"expected_transcript":"それぞれの世代には、それぞれの世代なりの価値観がある。"}'::jsonb, '価値観 (kachikan: nilai-nilai / pandangan hidup) dipadukan dengan ～なりの.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya pun telah memikirkan masalah ini matang-matang dengan cara saya sendiri."', '{"display_text":"私としても、私なりにこの件を真剣に検討してきました。","romaji":"Watashi to shite mo, watashi nari ni kono ken wo shinken ni kentou shite kimashita.","phonetic_breakdown":["wa-ta-shi","to","shi-te","mo","wa-ta-shi","na-ri","ni","ko-no","ken","wo","shin-ken","ni","ken-tou","shi-te","ki-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"私としても、私なりにこの件を真剣に検討してきました。"}'::jsonb, 'Ungkapan sopan dan tegas saat menyampaikan hasil pemikiran pribadi dalam forum kerja.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sesuai usianya, dia menunjukkan kedewasaan yang mengagumkan."', '{"tokens":["身につけて","落ち着いた","極まりない","なりに","判断力を","いる","をもって","年齢"],"target_translation":"Sesuai usianya, dia menunjukkan kedewasaan yang mengagumkan.","romaji":"Nenrei nari ni ochitsuita handanryoku wo mi ni tsukete iru."}'::jsonb, '["年齢","なりに","落ち着いた","判断力を","身につけて","いる"]'::jsonb, '年齢なりに berarti ''sesuai dengan usianya''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun bukan ahli, saya ingin berkontribusi sesuai kemampuan saya."', '{"tokens":["専門家で","自分","に至って","なりに","とはいえ","なくても","社会に","貢献したい"],"target_translation":"Meskipun bukan ahli, saya ingin berkontribusi sesuai kemampuan saya.","romaji":"Senmonka de nakute mo jibun nari ni shakai ni kouken shitai."}'::jsonb, '["専門家で","なくても","自分","なりに","社会に","貢献したい"]'::jsonb, '自分なりに社会に貢献したい berarti ''ingin berkontribusi pada masyarakat sesuai kapasitas diri sendiri''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Para pemula pun memiliki cara belajar tersendiri yang efektif."', '{"tokens":["ある","初心者","を余儀なく","はずだ","ながら","初心者には","学び方が","なりの"],"target_translation":"Para pemula pun memiliki cara belajar tersendiri yang efektif.","romaji":"Shoshinsha ni wa shoshinsha nari no manabikata ga aru hazu da."}'::jsonb, '["初心者には","初心者","なりの","学び方が","ある","はずだ"]'::jsonb, '初心者なりの学び方 berarti ''cara belajar tersendiri yang cocok bagi pemula''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Tes Akhir Unit 6', 'Tes Akhir U6', 'n1-u6-tes-akhir', 'trophy', 25, 5) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼は口数こそ少ないが、彼___周囲の仲間を気遣っている。', '{"options":["極まりなく","をもって","に至って","なりに"],"translation":"Dia memang sedikit bicara, tetapi dengan caranya sendiri ia memperhatikan rekan-rekan di sekitarnya.","sentence_template":"彼は口数こそ少ないが、彼[blank]周囲の仲間を気遣っている。"}'::jsonb, '{"selected":"なりに"}'::jsonb, '彼なりに menunjukkan bahwa meskipun tidak tampak menonjol, ia peduli dengan caranya sendiri.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 失敗に終わったとはいえ、その経験から得た自分___教訓は大きい。', '{"options":["ともなると","なりの","ならではの","なりに"],"translation":"Meskipun berakhir gagal, pelajaran tersendiri yang saya petik dari pengalaman itu sangat besar.","sentence_template":"失敗に終わったとはいえ、その経験から得た自分[blank]教訓は大きい。"}'::jsonb, '{"selected":"なりの"}'::jsonb, '自分なりの教訓 (pelajaran tersendiri bagi diri saya) memakai ～なりの karena diikuti kata benda 教訓.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan nasihat mentor berikut. Apa inti pesan yang ingin disampaikan?', '{"audio_text":"他人と比べるのではなく、今の自分の状況なりに一歩ずつ前進し続けることが成長につながる。","options":[{"id":"opt_1","text":"Kita harus selalu membandingkan diri dengan orang yang paling sukses"},{"id":"opt_2","text":"Terus maju selangkah demi selangkah sesuai kondisi diri sendiri membawa pertumbuhan"},{"id":"opt_3","text":"Jika kondisi belum ideal, sebaiknya berhenti berusaha sementara"},{"id":"opt_4","text":"Pertumbuhan hanya ditentukan oleh bakat bawaan sejak lahir"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '今の自分の状況なりに一歩ずつ前進し続ける berarti ''terus melangkah maju sesuai situasi diri saat ini''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar mengenai proyek desa berikut. Apa yang dicapai oleh warga setempat?', '{"audio_text":"資金や人手が乏しいなら乏しいなりに、住民たちが知恵を出し合って魅力的な特産品を生み出した。","options":[{"id":"opt_1","text":"Proyek dibatalkan karena tidak ada dana sama sekali"},{"id":"opt_2","text":"Pemerintah pusat mengirimkan ratusan tenaga ahli ke desa"},{"id":"opt_3","text":"Warga menyerahkan seluruh produksi kepada perusahaan asing"},{"id":"opt_4","text":"Di tengah keterbatasan dana dan tenaga, warga urun gagasan melahirkan produk khas menarik"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '乏しいなら乏しいなりに (sesuai kondisi serba terbatas) warga tetap melahirkan produk unggulan.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setiap departemen telah menyiapkan rencana perbaikan dengan caranya sendiri."', '{"tokens":["きた","とはいえ","に足る","それぞれ","なりに","各部署が","まとめて","改善策を"],"target_translation":"Setiap departemen telah menyiapkan rencana perbaikan dengan caranya sendiri.","romaji":"Kaku busho ga sorezore nari ni kaizensaku wo matomete kita."}'::jsonb, '["各部署が","それぞれ","なりに","改善策を","まとめて","きた"]'::jsonb, 'それぞれなりに berarti ''masing-masing dengan caranya sendiri''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Beban kerja yang tinggi memang berat, tetapi ada kepuasan tersendiri di dalamnya."', '{"display_text":"責任が重い分、そこにはそこなりのやりがいがある。","romaji":"Sekinin ga omoi bun, soko ni wa soko nari no yarigai ga aru.","phonetic_breakdown":["se-ki-nin","ga","o-moi","bun","so-ko","ni","wa","so-ko","na-ri","no","ya-ri-gai","ga","a-ru"]}'::jsonb, '{"expected_transcript":"責任が重い分、そこにはそこなりのやりがいがある。"}'::jsonb, 'そこにはそこなりのやりがいがある menunjukkan bahwa setiap tanggung jawab membawa rasa bermakna tersendiri.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index) VALUES (v_level_id, 'Pasti Menimbulkan Efek (～ずにはおかない)', 'Analisis dampak karya seni, kebijakan publik, serta reaksi psikologis sosial yang niscaya dan tak terbendung dalam wacana N1.', 'curriculum', 7) RETURNING id INTO v_unit_id;
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kosakata Dampak & Psikologi Sosial', 'Kosakata Dampak', 'n1-u7-kosakata', 'lightbulb', 15, 1) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk berita politik: 突然の増税発表は、国民の激しい___を招いた。', '{"options":["称賛","反発","歓迎","妥協"],"translation":"Pengumuman kenaikan pajak mendadak memicu penolakan keras dari masyarakat.","sentence_template":"突然の増税発表は、国民の激しい[blank]を招いた。"}'::jsonb, '{"selected":"反発"}'::jsonb, '反発を招く (hanpatsu wo maneku) berarti ''mengundang reaksi penolakan/perlawanan''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ulasan budaya berikut: その独創的な演出は、世界中の観客を___した。', '{"options":["困惑","失望","退屈","魅了"],"translation":"Penyutradaraan yang orisinal itu memikat penonton di seluruh dunia.","sentence_template":"その独創的な演出は、世界中の観客を[blank]した。"}'::jsonb, '{"selected":"魅了"}'::jsonb, '魅了する (miryou suru) berarti ''mempesona / memikat hati secara mendalam''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat untuk wacana publik: 新しい法案をめぐり、専門家の間でも強い___が広がっている。', '{"options":["歓喜","確信","懸念","無関心"],"translation":"Terkait rancangan undang-undang baru, kekhawatiran kuat pun meluas di kalangan para pakar.","sentence_template":"新しい法案をめぐり、専門家の間でも強い[blank]が広がっている。"}'::jsonb, '{"selected":"懸念"}'::jsonb, '懸念 (kenen) berarti ''kekhawatiran / rasa cemas yang beralasan'' dalam bahasa berita formal.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan ulasan film berikut. Bagaimana reaksi penonton terhadap film dokumenter tersebut?', '{"audio_text":"戦時下の日常を描いたこの記録映画は、世代を超えて深い共感と議論を呼び起こしている。","options":[{"id":"opt_1","text":"Film itu membangkitkan empati mendalam dan diskusi lintas generasi"},{"id":"opt_2","text":"Film itu hanya ditonton oleh kalangan sejarawan saja"},{"id":"opt_3","text":"Penonton menilai alur ceritanya terlalu ringan dan komedis"},{"id":"opt_4","text":"Penayangannya dihentikan karena kurang peminat"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '深い共感と議論を呼び起こしている berarti ''membangkitkan empati mendalam dan perdebatan/diskusi''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan berita ilmu pengetahuan berikut. Mengapa penemuan itu menjadi sorotan global?', '{"audio_text":"従来の定説を覆す今回の発見は、物理学界全体に大きな衝撃を与えた。","options":[{"id":"opt_1","text":"Karena hanya mengulang hasil penelitian lima puluh tahun lalu"},{"id":"opt_2","text":"Karena mematahkan teori mapan sebelumnya dan mengguncang dunia fisika"},{"id":"opt_3","text":"Karena penelitian tersebut dibatalkan sebelum dipublikasikan"},{"id":"opt_4","text":"Karena biayanya sangat kecil dibandingkan proyek lain"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '従来の定説を覆す (membalikkan teori baku sebelumnya) dan 大きな衝撃を与えた (memberi guncangan besar).', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pernyataan tersebut mendapat pujian luas dari komunitas internasional."', '{"display_text":"その英断は国際社会から広く称賛を浴びた。","romaji":"Sono eidan wa kokusai shakai kara hiroku shousan wo abita.","phonetic_breakdown":["so-no","ei-dan","wa","ko-ku-sai","sha-kai","ka-ra","hi-ro-ku","shou-san","wo","a-bi-ta"]}'::jsonb, '{"expected_transcript":"その英断は国際社会から広く称賛を浴びた。"}'::jsonb, '称賛を浴びる (shousan wo abiru) berarti ''dibanjiri pujian'', sedangkan 英断 (eidan) berarti ''keputusan berani dan bijak''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Pola ～ずにはおかない', 'Pola ずにはおかない', 'n1-u7-pola-utama', 'sparkle', 20, 2) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat ulasan seni berikut: 彼女の力強い歌声は、聴く者すべてを感動させ___。', '{"options":["ずにはおかない","ざるを得ない","かねない","に足らない"],"translation":"Suara nyanyiannya yang penuh daya pasti akan menggetarkan hati setiap pendengarnya.","sentence_template":"彼女の力強い歌声は、聴く者すべてを感動させ[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, 'Kata kerja (bentuk nai, ganti ない -> ず) + にはおかない menyatakan bahwa sesuatu pasti/niscaya menimbulkan efek tertentu.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk kata kerja する: このスキャンダルは、政権の支持率に深刻な打撃を与えず___。', '{"options":["にはかなわない","にはいられない","にはすまない","にはおかない"],"translation":"Skandal ini pasti akan memberikan pukulan serius pada tingkat dukungan pemerintah.","sentence_template":"このスキャンダルは、政権の支持率に深刻な打撃を与えず[blank]。"}'::jsonb, '{"selected":"にはおかない"}'::jsonb, '与えずにはおかない berarti ''niscaya akan memberikan (pukulan serius)'' secara objektif/tak terelakkan.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat yang menyatakan tekad kuat berikut: 今回の不当な扱いに対しては、必ず真相を究明し___。', '{"options":["どころではない","ようがない","かねない","ないではおかない"],"translation":"Terhadap perlakuan tidak adil kali ini, saya bertekad pasti akan mengungkap kebenarannya.","sentence_template":"今回の不当な扱いに対しては、必ず真相を究明し[blank]。"}'::jsonb, '{"selected":"ないではおかない"}'::jsonb, '～ないではおかない (atau せずにはおかない) juga digunakan untuk menyatakan tekad kuat pembicara bahwa ia pasti akan melakukannya.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kebijakan itu pasti akan memicu perdebatan sengit di masyarakat."', '{"tokens":["をもって","なりに","巻き起こさ","激しい","社会に","議論を","その政策は","ずにはおかない"],"target_translation":"Kebijakan itu pasti akan memicu perdebatan sengit di masyarakat.","romaji":"Sono seisaku wa shakai ni hageshii giron wo makiokosazu ni wa okanai."}'::jsonb, '["その政策は","社会に","激しい","議論を","巻き起こさ","ずにはおかない"]'::jsonb, '議論を巻き起こす (membangkitkan perdebatan) -> 巻き起こさずにはおかない (pasti akan membangkitkan perdebatan).', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Keindahan pemandangan itu pasti memukau siapa pun yang melihatnya."', '{"tokens":["心を","見る人の","とはいえ","ずには","おかない","に至って","その絶景は","奪わ"],"target_translation":"Keindahan pemandangan itu pasti memukau siapa pun yang melihatnya.","romaji":"Sono zekkei wa miru hito no kokoro wo ubawazu ni wa okanai."}'::jsonb, '["その絶景は","見る人の","心を","奪わ","ずには","おかない"]'::jsonb, '心を奪う (memikat/merenggut hati) -> 奪わずにはおかない.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Laporan tersebut pasti akan mengubah cara pandang publik."', '{"display_text":"その調査報告は、世論の認識を変えずにはおかないだろう。","romaji":"Sono chousa houkoku wa, seron no ninshiki wo kaezu ni wa okanai darou.","phonetic_breakdown":["so-no","chou-sa","hou-ko-ku","wa","se-ron","no","nin-shi-ki","wo","ka-e-zu","ni","wa","o-ka-nai","da-rou"]}'::jsonb, '{"expected_transcript":"その調査報告は、世論の認識を変えずにはおかないだろう。"}'::jsonb, '変えずにはおかないだろう berarti ''pasti akan mengubah (persepsi opini publik)''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Dampak Karya & Kebijakan Publik', 'Dengar & Baca U7', 'n1-u7-dengar-baca', 'play-circle', 20, 3) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan resensi buku berikut. Bagaimana efek novel tersebut terhadap pembacanya?', '{"audio_text":"人間の孤独を鋭く描いたこの小説は、読者に深い思索を促さずにはおかない傑作だ。","options":[{"id":"opt_1","text":"Novel itu membuat pembaca mengantuk karena alurnya datar"},{"id":"opt_2","text":"Novel itu hanya cocok dibaca sebagai hiburan ringan di kereta"},{"id":"opt_3","text":"Novel itu pasti mendorong pembaca merenung secara mendalam"},{"id":"opt_4","text":"Novel itu mendapat kritik keras karena temanya dangkal"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '深い思索を促さずにはおかない berarti ''pasti mendorong perenungan mendalam''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan analisis pasar berikut. Apa dampak merger dua perusahaan besar tersebut?', '{"audio_text":"業界大手二社の経営統合は、今後の市場構造を大きく変革せずにはおかない。","options":[{"id":"opt_1","text":"Tidak akan membawa perubahan berarti bagi struktur pasar"},{"id":"opt_2","text":"Pasti akan merombak besar-besaran struktur pasar di masa mendatang"},{"id":"opt_3","text":"Dibatalkan oleh otoritas pengawas persaingan usaha"},{"id":"opt_4","text":"Hanya memengaruhi satu cabang kecil di luar negeri"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '市場構造を大きく変革せずにはおかない berarti ''pasti akan mentransformasi struktur pasar secara besar-besaran''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan pengacara berikut. Apa tekad yang disampaikannya?', '{"audio_text":"被害者の名誉を回復するため、どのような困難があろうとも責任を追及せずにはおかない。","options":[{"id":"opt_1","text":"Akan menghentikan gugatan jika prosesnya terlalu lama"},{"id":"opt_2","text":"Menyerahkan seluruh penyelesaian kepada pihak lawan"},{"id":"opt_3","text":"Tidak akan mengajukan tuntutan apa pun di pengadilan"},{"id":"opt_4","text":"Bertekad pasti menuntut pertanggungjawaban demi memulihkan nama baik korban meski penuh kesulitan"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '責任を追及せずにはおかない mengekspresikan tekad tak tergoyahkan untuk menuntut pertanggungjawaban.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi komentar budaya berikut: 職人の妥協なき技は、見る者に深い感銘を与え___。', '{"options":["わけにはいかない","ずにはおかない","ざるを得ない","に過ぎない"],"translation":"Keahlian tanpa kompromi sang perajin pasti meninggalkan kesan mendalam bagi siapa pun yang menyaksikannya.","sentence_template":"職人の妥協なき技は、見る者に深い感銘を与え[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, '深い感銘を与えずにはおかない berarti ''pasti memberikan kesan mendalam''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih bentuk konjugasi yang benar untuk する: 彼の率直な問題提起は、会議の雰囲気を一変___。', '{"options":["しずにはおかない","すずにはおかない","さずにはおかない","せずにはおかない"],"translation":"Pengajuan masalah yang lugas darinya pasti akan mengubah suasana rapat secara drastis.","sentence_template":"彼の率直な問題提起は、会議の雰囲気を一変[blank]。"}'::jsonb, '{"selected":"せずにはおかない"}'::jsonb, 'Bentuk ず dari kata kerja する selalu せず (bukan しず), sehingga menjadi 一変せずにはおかない.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kritik sosial berikut: 格差の固定化は、将来的に社会の分断を深刻化させ___。', '{"options":["なりに","とはいえ","をもって","ずにはおかない"],"translation":"Mengakarnya kesenjangan pasti akan memperparah perpecahan sosial di masa depan.","sentence_template":"格差の固定化は、将来的に社会の分断を深刻化させ[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, '深刻化させずにはおかない menegaskan konsekuensi sosial yang tak terhindarkan.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Bicara & Rakit Analisis Dampak', 'Bicara & Rakit U7', 'n1-u7-bicara-rakit', 'microphone', 20, 4) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pidato yang tulus itu pasti menggerakkan hati para pendengar."', '{"display_text":"あの心のこもった演説は、聴衆の胸を打たずにはおかない。","romaji":"Ano kokoro no komotta enzetsu wa, choushuu no mune wo utazu ni wa okanai.","phonetic_breakdown":["a-no","ko-ko-ro","no","ko-mo-tta","en-ze-tsu","wa","chou-shuu","no","mu-ne","wo","u-ta-zu","ni","wa","o-ka-nai"]}'::jsonb, '{"expected_transcript":"あの心のこもった演説は、聴衆の胸を打たずにはおかない。"}'::jsonb, '胸を打つ (mune wo utsu: menyentuh/menggetarkan hati) -> 打たずにはおかない.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Inovasi teknologi ini pasti akan mengubah cara kerja kita."', '{"display_text":"この技術革新は、私たちの働き方を根本から変えずにはおかない。","romaji":"Kono gijutsu kakushin wa, watashitachi no hatarakikata wo konpon kara kaezu ni wa okanai.","phonetic_breakdown":["ko-no","gi-ju-tsu","ka-ku-shin","wa","wa-ta-shi-ta-chi","no","ha-ta-ra-ki-ka-ta","wo","kon-pon","ka-ra","ka-e-zu","ni","wa","o-ka-nai"]}'::jsonb, '{"expected_transcript":"この技術革新は、私たちの働き方を根本から変えずにはおかない。"}'::jsonb, '根本から変える (mengubah dari akarnya) dipadukan dengan ～ずにはおかない.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sikap yang arogan itu pasti akan memicu ketidakpercayaan mitra."', '{"display_text":"ああした高圧的な態度は、取引先の不信感を招かずにはおかない。","romaji":"Aa shita kouatsuteki na taido wa, torihikisaki no fushinkan wo manekazu ni wa okanai.","phonetic_breakdown":["aa","shi-ta","kou-a-tsu-te-ki","na","tai-do","wa","to-ri-hi-ki-sa-ki","no","fu-shin-kan","wo","ma-ne-ka-zu","ni","wa","o-ka-nai"]}'::jsonb, '{"expected_transcript":"ああした高圧的な態度は、取引先の不信感を招かずにはおかない。"}'::jsonb, '高圧的な態度 (sikap menekan/arogan) pasti mengundang 不信感 (rasa tidak percaya).', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Berita mengejutkan itu pasti menimbulkan gejolak di pasar keuangan."', '{"tokens":["極まりない","動揺を","なりに","その","与え","ずにはおかない","金融市場に","速報は"],"target_translation":"Berita mengejutkan itu pasti menimbulkan gejolak di pasar keuangan.","romaji":"Sono sokuhou wa kin''yuu shijou ni douyou wo ataezu ni wa okanai."}'::jsonb, '["その","速報は","金融市場に","動揺を","与え","ずにはおかない"]'::jsonb, '動揺を与える (menimbulkan keguncangan/gejolak) -> 与えずにはおかない.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dedikasi mereka pasti akan membangkitkan rasa hormat siapa pun."', '{"tokens":["彼らの","敬意を","活動は","献身的な","とはいえ","抱かせ","をもって","ずにはおかない"],"target_translation":"Dedikasi mereka pasti akan membangkitkan rasa hormat siapa pun.","romaji":"Karera no kenshinteki na katsudou wa keii wo idakasezu ni wa okanai."}'::jsonb, '["彼らの","献身的な","活動は","敬意を","抱かせ","ずにはおかない"]'::jsonb, '敬意を抱かせる (membuat orang menaruh rasa hormat) -> 抱かせずにはおかない.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya bertekad pasti akan menyelesaikan proyek ini hingga tuntas."', '{"tokens":["成功","計画は","必ず","ないではおかない","この","ながら","させ","に至って"],"target_translation":"Saya bertekad pasti akan menyelesaikan proyek ini hingga tuntas.","romaji":"Kono keikaku wa kanarazu seikou sasenai de wa okanai."}'::jsonb, '["この","計画は","必ず","成功","させ","ないではおかない"]'::jsonb, '成功させないではおかない menyatakan tekad kuat untuk menyukseskan proyek.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Tes Akhir Unit 7', 'Tes Akhir U7', 'n1-u7-tes-akhir', 'trophy', 25, 5) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼の圧倒的な演奏は、会場にいたすべての聴衆を魅了___。', '{"options":["しずにはおかない","を余儀なくされた","するに足らない","せずにはおかない"],"translation":"Permainan musiknya yang memukau pasti mempesona seluruh hadirin di gedung konser.","sentence_template":"彼の圧倒的な演奏は、会場にいたすべての聴衆を魅了[blank]。"}'::jsonb, '{"selected":"せずにはおかない"}'::jsonb, '魅了する -> 魅了せずにはおかない (''pasti memikat hati'').', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat analisis kebijakan berikut: 事実を隠蔽しようとする動きは、世論のさらなる反発を招か___。', '{"options":["ずにはすまない","ざるを得ない","かねない","ずにはおかない"],"translation":"Upaya menutupi fakta pasti akan mengundang penolakan publik yang lebih keras lagi.","sentence_template":"事実を隠蔽しようとする動きは、世論のさらなる反発を招か[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, '反発を招かずにはおかない menegaskan efek sosial yang pasti terjadi.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar kritikus film berikut. Apa dampak dari adegan penutup film itu?', '{"audio_text":"静寂の中に深い余韻を残すラストシーンは、観る者の心に強い印象を刻まずにはおかない。","options":[{"id":"opt_1","text":"Adegan penutupnya pasti menorehkan kesan kuat di hati penonton"},{"id":"opt_2","text":"Adegan penutupnya sangat bising dan sulit diikuti"},{"id":"opt_3","text":"Penonton langsung melupakan film itu begitu keluar bioskop"},{"id":"opt_4","text":"Adegan penutupnya dipotong dari versi rilis internasional"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '強い印象を刻まずにはおかない berarti ''pasti mengukir kesan yang kuat''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan ekonomi berikut. Apa prediksi pembicara terhadap keputusan bank sentral?', '{"audio_text":"中央銀行による今回の利上げ決定は、国内外の投資家の判断に多大な影響を与えずにはおかないだろう。","options":[{"id":"opt_1","text":"Investor tidak akan bereaksi terhadap kenaikan suku bunga"},{"id":"opt_2","text":"Bank sentral memutuskan menurunkan suku bunga menjadi nol"},{"id":"opt_3","text":"Keputusan kenaikan suku bunga pasti berpengaruh besar pada keputusan investor domestik dan asing"},{"id":"opt_4","text":"Pengumuman suku bunga ditunda hingga kuartal berikutnya"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '多大な影響を与えずにはおかないだろう berarti ''pasti akan membawa dampak sangat besar''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karya lukis yang penuh emosi itu pasti menggetarkan jiwa penikmatnya."', '{"tokens":["とはいえ","魂を","揺さぶらずにはおかない","情熱に","なりに","満ちた","その絵画は","観る者の"],"target_translation":"Karya lukis yang penuh emosi itu pasti menggetarkan jiwa penikmatnya.","romaji":"Jounetsu ni michita sono kaiga wa miru mono no tamashii wo yusaburazu ni wa okanai."}'::jsonb, '["情熱に","満ちた","その絵画は","観る者の","魂を","揺さぶらずにはおかない"]'::jsonb, '魂を揺さぶる (mengguncang/menggetarkan jiwa) -> 揺さぶらずにはおかない.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Keputusan bersejarah ini pasti akan mengubah arah masa depan negara."', '{"display_text":"この歴史的な決断は、国の将来を大きく左右せずにはおかない。","romaji":"Kono rekishiteki na ketsudan wa, kuni no shourai wo ookiku sayuu sezu ni wa okanai.","phonetic_breakdown":["ko-no","re-ki-shi-te-ki","na","ke-tsu-dan","wa","ku-ni","no","shou-rai","wo","oo-ki-ku","sa-yuu","se-zu","ni","wa","o-ka-nai"]}'::jsonb, '{"expected_transcript":"この歴史的な決断は、国の将来を大きく左右せずにはおかない。"}'::jsonb, '左右する (sayuu suru: menentukan/memengaruhi arah secara besar) -> 左右せずにはおかない.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index) VALUES (v_level_id, 'Jika Sudah Sampai Level (～ともなると)', 'Bahas standar eksekutif, proyek berskala besar, serta ekspektasi dan tanggung jawab tinggi yang menyertai posisi prestisius.', 'curriculum', 8) RETURNING id INTO v_unit_id;
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kosakata Eksekutif & Skala Besar', 'Kosakata Eksekutif', 'n1-u8-kosakata', 'briefcase', 15, 1) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah korporasi yang tepat: 東証プライム市場の___には、極めて高い情報開示の透明性が求められる。', '{"options":["個人商店","任意団体","同好会","上場企業"],"translation":"Perusahaan terbuka di pasar Prime Bursa Tokyo dituntut memiliki transparansi keterbukaan informasi yang sangat tinggi.","sentence_template":"東証プライム市場の[blank]には、極めて高い情報開示の透明性が求められる。"}'::jsonb, '{"selected":"上場企業"}'::jsonb, '上場企業 (joujou kigyou) berarti ''perusahaan tercatat/terbuka (Tbk)'' di bursa efek.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tata kelola perusahaan berikut: 重要な買収案件は、___の承認を経て正式に決定される。', '{"options":["懇親会","町内会","同窓会","取締役会"],"translation":"Rencana akuisisi penting diputuskan secara resmi setelah melalui persetujuan dewan direksi.","sentence_template":"重要な買収案件は、[blank]の承認を経て正式に決定される。"}'::jsonb, '{"selected":"取締役会"}'::jsonb, '取締役会 (torishimariyakukai) berarti ''rapat/dewan direksi (Board of Directors)''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk konteks kebijakan makro: ___の編成にあたっては、将来の世代への負担も考慮しなければならない。', '{"options":["領収書","国家予算","家計簿","小遣い"],"translation":"Dalam penyusunan anggaran negara, beban bagi generasi mendatang juga harus diperhitungkan.","sentence_template":"[blank]の編成にあたっては、将来の世代への負担も考慮しなければならない。"}'::jsonb, '{"selected":"国家予算"}'::jsonb, '国家予算の編成 berarti ''penyusunan anggaran pendapatan dan belanja negara (APBN)''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan kepala keamanan berikut. Apa yang dipersiapkan untuk acara tersebut?', '{"audio_text":"各国首脳が集う国際会議の開催にあたり、例年にない厳重な警備体制が敷かれている。","options":[{"id":"opt_1","text":"Sistem pengamanan yang sangat ketat dan luar biasa diterapkan menyambut konferensi para pemimpin negara"},{"id":"opt_2","text":"Konferensi dibuka bebas untuk umum tanpa pemeriksaan identitas"},{"id":"opt_3","text":"Jumlah petugas keamanan dikurangi demi menghemat anggaran"},{"id":"opt_4","text":"Acara dipindahkan ke luar ruangan di taman kota"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '厳重な警備体制が敷かれている berarti ''sistem pengamanan ketat diberlakukan''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan komentar pelatih olahraga berikut. Apa perbedaan turnamen tingkat dunia?', '{"audio_text":"世界選手権の決勝の舞台では、技術だけでなく極限の精神力が勝敗を分ける。","options":[{"id":"opt_1","text":"Hanya keberuntungan semata yang menentukan pemenang"},{"id":"opt_2","text":"Bukan hanya teknik, melainkan ketangguhan mental ekstrem yang menentukan menang-kalah"},{"id":"opt_3","text":"Atlet tidak perlu berlatih teknik sebelum bertanding"},{"id":"opt_4","text":"Pertandingan final selalu berakhir seri"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '極限の精神力が勝敗を分ける berarti ''kekuatan mental di titik ekstrem menentukan kemenangan atau kekalahan''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Semakin tinggi jabatan, semakin besar pula tanggung jawab sosialnya."', '{"display_text":"役職が上がるほど、社会的な責任も重くなる。","romaji":"Yakushoku ga agaru hodo, shakaiteki na sekinin mo omoku naru.","phonetic_breakdown":["ya-ku-sho-ku","ga","a-ga-ru","ho-do","sha-kai-te-ki","na","se-ki-nin","mo","o-mo-ku","na-ru"]}'::jsonb, '{"expected_transcript":"役職が上がるほど、社会的な責任も重くなる。"}'::jsonb, '社会的な責任 (tanggung jawab sosial) meningkat seiring tingginya 役職 (jabatan).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Pola ～ともなると & ～ともなれば', 'Pola ～ともなると', 'n1-u8-pola-utama', 'sparkle', 20, 2) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 企業の社長___、一言の発言が株価に大きな影響を与えかねない。', '{"options":["なりに","をもって","ともなると","とはいえ"],"translation":"Jika sudah sampai level direktur utama perusahaan, sepatah kata saja bisa berdampak besar pada harga saham.","sentence_template":"企業の社長[blank]、一言の発言が株価に大きな影響を与えかねない。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, 'Kata benda + ともなると menyatakan bahwa jika sudah mencapai status/skala/tahap tinggi tersebut, wajar muncul konsekuensi atau standar tinggi.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk konteks skala proyek: 総工費が数百億円規模のプロジェクト___、関係省庁との調整だけで数年を要する。', '{"options":["ともなれば","に至っては","をよそに","に足らず"],"translation":"Kalau sudah proyek berskala puluhan miliar yen, koordinasi dengan kementerian terkait saja membutuhkan beberapa tahun.","sentence_template":"総工費が数百億円規模のプロジェクト[blank]、関係省庁との調整だけで数年を要する。"}'::jsonb, '{"selected":"ともなれば"}'::jsonb, '～ともなれば memiliki makna setara dengan ～ともなると, menyoroti skala besar proyek.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat mengenai tahapan ujian berikut: JLPTのN1レベル___、新聞の社説や専門的な論説文を読み解く力が求められる。', '{"options":["極まりなく","ずにはおかない","を余儀なく","ともなると"],"translation":"Jika sudah sampai level JLPT N1, dituntut kemampuan memahami tajuk rencana koran dan esai ilmiah.","sentence_template":"JLPTのN1レベル[blank]、新聞の社説や専門的な論説文を読み解く力が求められる。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, 'N1レベルともなると menekankan tingginya ekspektasi kemampuan pada level tertinggi.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah memasuki bulan Desember, kota menjadi sangat sibuk."', '{"tokens":["なりに","をもって","ともなると","街は","慌ただしく","十二月","なる","一気に"],"target_translation":"Jika sudah memasuki bulan Desember, kota menjadi sangat sibuk.","romaji":"Juunigatsu to mo naru to machi wa ikki ni awatadashiku naru."}'::jsonb, '["十二月","ともなると","街は","一気に","慌ただしく","なる"]'::jsonb, '～ともなると juga dapat dipakai untuk musim/waktu tertentu yang menandai perubahan suasana khas.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kalau sudah sekelas pakar internasional, jadwalnya penuh sepanjang tahun."', '{"tokens":["埋まっている","とはいえ","に至って","一年先まで","世界的な","予定が","ともなれば","専門家"],"target_translation":"Kalau sudah sekelas pakar internasional, jadwalnya penuh sepanjang tahun.","romaji":"Sekaiteki na senmonka to mo nareba yotei ga ichinen saki made umatte iru."}'::jsonb, '["世界的な","専門家","ともなれば","予定が","一年先まで","埋まっている"]'::jsonb, '世界的な専門家ともなれば menekankan status prestisius yang membawa kesibukan luar biasa.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjadi cabang utama, jumlah pengunjung harian mencapai puluhan ribu."', '{"display_text":"都心の旗艦店ともなると、一日の来店客数は数万人に及ぶ。","romaji":"Toshin no kikanten to mo naru to, ichinichi no raiten kyakusuu wa suumannin ni oyobu.","phonetic_breakdown":["to-shin","no","ki-kan-ten","to","mo","na-ru","to","i-chi-ni-chi","no","rai-ten","kya-ku-suu","wa","suu-man-nin","ni","o-yo-bu"]}'::jsonb, '{"expected_transcript":"都心の旗艦店ともなると、一日の来店客数は数万人に及ぶ。"}'::jsonb, '旗艦店 (kikanten: toko flagship) dan 数万人に及ぶ (mencapai puluhan ribu orang).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Standar Global & Ekspektasi Tinggi', 'Dengar & Baca U8', 'n1-u8-dengar-baca', 'play-circle', 20, 3) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan ulasan karier berikut. Apa yang dituntut pada posisi kepala divisi?', '{"audio_text":"事業部長ともなると、目先の業績だけでなく五年先を見据えた戦略立案が求められる。","options":[{"id":"opt_1","text":"Hanya fokus pada laporan penjualan harian saja"},{"id":"opt_2","text":"Tidak perlu terlibat dalam penyusunan strategi jangka panjang"},{"id":"opt_3","text":"Dituntut menyusun strategi lima tahun ke depan, bukan sekadar kinerja sesaat"},{"id":"opt_4","text":"Menyerahkan seluruh target kinerja kepada tim pemasaran"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '五年先を見据えた戦略立案 (penyusunan strategi dengan memandang lima tahun ke depan).', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan acara olahraga berikut. Mengapa persiapan dilakukan bertahun-tahun sebelumnya?', '{"audio_text":"国際的な大規模スポーツ大会の開催ともなれば、交通インフラの整備から宿泊施設の確保まで膨大な準備が必要になる。","options":[{"id":"opt_1","text":"Karena persiapan besar mulai dari infrastruktur transportasi hingga akomodasi sangat dibutuhkan"},{"id":"opt_2","text":"Karena panitia baru dibentuk dua minggu sebelum pembukaan"},{"id":"opt_3","text":"Karena jumlah penonton dibatasi hanya seratus orang"},{"id":"opt_4","text":"Karena seluruh pertandingan diadakan secara daring"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '交通インフラの整備から宿泊施設の確保まで menunjukkan cakupan persiapan berskala raksasa.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan komentar akademisi berikut. Apa yang berubah ketika masuk program doktoral?', '{"audio_text":"大学院の博士課程ともなると、既存の知識を学ぶのではなく自ら新たな知見を生み出す力が試される。","options":[{"id":"opt_1","text":"Mahasiswa cukup menghafal buku teks dasar"},{"id":"opt_2","text":"Tidak ada kewajiban menulis karya ilmiah"},{"id":"opt_3","text":"Seluruh penelitian dilakukan sepenuhnya oleh dosen pembimbing"},{"id":"opt_4","text":"Diuji kemampuan menghasilkan temuan baru sendiri, bukan sekadar mempelajari ilmu yang ada"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '自ら新たな知見を生み出す力が試される berarti ''kemampuan melahirkan pengetahuan baru sendiri yang diuji''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 社員数が一万人を超える大企業___、社内コミュニケーションの仕組みづくりが不可欠だ。', '{"options":["ともなると","とはいえ","極まりなく","を余儀なく"],"translation":"Jika sudah perusahaan besar dengan lebih dari sepuluh ribu karyawan, pembangunan sistem komunikasi internal mutlak diperlukan.","sentence_template":"社員数が一万人を超える大企業[blank]、社内コミュニケーションの仕組みづくりが不可欠だ。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, '大企業ともなると menyoroti kebutuhan sistemik yang muncul pada skala organisasi besar.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat: 国を代表する外交官___、高い語学力のみならず深い歴史的教養も不可欠である。', '{"options":["ともなれば","に至っては","をもって","なりに"],"translation":"Jika sudah menjadi diplomat yang mewakili negara, bukan hanya kemahiran bahasa tinggi melainkan wawasan sejarah mendalam pun mutlak diperlukan.","sentence_template":"国を代表する外交官[blank]、高い語学力のみならず深い歴史的教養も不可欠である。"}'::jsonb, '{"selected":"ともなれば"}'::jsonb, '国を代表する外交官ともなれば menekankan standar tinggi yang menyertai jabatan diplomat.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 創業百年の老舗___、伝統を守りつつ時代に合わせた革新も続けている。', '{"options":["いかんによらず","に足らず","ともなると","をよそに"],"translation":"Jika sudah toko legendaris berusia seratus tahun, mereka menjaga tradisi sekaligus terus berinovasi mengikuti zaman.","sentence_template":"創業百年の老舗[blank]、伝統を守りつつ時代に合わせた革新も続けている。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, '老舗 (shinise: usaha/toko mapan turun-temurun) + ともなると.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Bicara & Rakit Standar Profesional', 'Bicara & Rakit U8', 'n1-u8-bicara-rakit', 'microphone', 20, 4) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjadi proyek nasional, pengawasan publik sangat ketat."', '{"display_text":"国家的な事業ともなると、国民の監視の目も極めて厳しい。","romaji":"Kokkateki na jigyou to mo naru to, kokumin no kanshi no me mo kiwamete kibishii.","phonetic_breakdown":["ko-kka-te-ki","na","ji-gyou","to","mo","na-ru","to","ko-ku-min","no","kan-shi","no","me","mo","ki-wa-me-te","ki-bi-shii"]}'::jsonb, '{"expected_transcript":"国家的な事業ともなると、国民の監視の目も極めて厳しい。"}'::jsonb, '監視の目 (sorotan pengawasan) sangat ketat pada 国家的な事業 (proyek nasional).', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau sudah sekelas orkestra ternama, tiketnya langsung terjual habis."', '{"display_text":"世界一流のオーケストラともなれば、チケットは発売と同時に完売する。","romaji":"Sekai ichiryuu no ookesutora to mo nareba, chiketto wa hatsubai to douji ni kanbai suru.","phonetic_breakdown":["se-kai","i-chi-ryuu","no","oo-ke-su-to-ra","to","mo","na-re-ba","chi-ke-tto","wa","ha-tsu-bai","to","dou-ji","ni","kan-bai","su-ru"]}'::jsonb, '{"expected_transcript":"世界一流のオーケストラともなれば、チケットは発売と同時に完売する。"}'::jsonb, '発売と同時に完売する berarti ''langsung habis terjual begitu mulai dipasarkan''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah mencapai jabatan direktur, keputusan harus diambil dengan cepat."', '{"display_text":"役員クラスともなると、不確実な状況でも迅速な決断が求められる。","romaji":"Yakuin kurasu to mo naru to, fukakujitsu na joukyou demo jinsoku na ketsudan ga motomerareru.","phonetic_breakdown":["ya-ku-in","ku-ra-su","to","mo","na-ru","to","fu-ka-ku-ji-tsu","na","jou-kyou","de-mo","jin-so-ku","na","ke-tsu-dan","ga","mo-to-me-ra-re-ru"]}'::jsonb, '{"expected_transcript":"役員クラスともなると、不確実な状況でも迅速な決断が求められる。"}'::jsonb, '役員クラス (kalangan eksekutif/direksi) dituntut 迅速な決断 (keputusan cepat).', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah memimpin tim multinasional, pemahaman lintas budaya sangat penting."', '{"tokens":["ともなると","チームの","多国籍","極まりない","異文化理解が","をもって","リーダー","欠かせない"],"target_translation":"Jika sudah memimpin tim multinasional, pemahaman lintas budaya sangat penting.","romaji":"Takokuseki chiimu no riidaa to mo naru to ibunka rikai ga kakasenai."}'::jsonb, '["多国籍","チームの","リーダー","ともなると","異文化理解が","欠かせない"]'::jsonb, '異文化理解が欠かせない berarti ''pemahaman lintas budaya mutlak tak tergantikan''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kalau sudah selevel profesor terkemuka, karyanya dikutip di seluruh dunia."', '{"tokens":["著名な","引用される","教授","なりに","論文が","とはいえ","世界中で","ともなれば"],"target_translation":"Kalau sudah selevel profesor terkemuka, karyanya dikutip di seluruh dunia.","romaji":"Chomei na kyouju to mo nareba ronbun ga sekaijuu de in''you sareru."}'::jsonb, '["著名な","教授","ともなれば","論文が","世界中で","引用される"]'::jsonb, '引用される berarti ''dikutip/disitasi'' dalam dunia akademik.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah akhir musim dingin, salju mulai mencair perlahan."', '{"tokens":["雪も","三月の","ともなると","山間部の","に至って","下旬","溶け始める","ながら"],"target_translation":"Jika sudah akhir musim dingin, salju mulai mencair perlahan.","romaji":"Sangatsu no gejun to mo naru to sankanbu no yuki mo tokehajimeru."}'::jsonb, '["三月の","下旬","ともなると","山間部の","雪も","溶け始める"]'::jsonb, '三月の下旬ともなると (jika sudah memasuki akhir Maret) menandai pergantian musim.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Tes Akhir Unit 8', 'Tes Akhir U8', 'n1-u8-tes-akhir', 'trophy', 25, 5) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: グローバルに展開する企業___、各国の法規制や環境基準への対応が不可欠だ。', '{"options":["とはいえ","なりに","をもって","ともなると"],"translation":"Jika sudah menjadi perusahaan yang berekspansi secara global, kepatuhan terhadap regulasi hukum dan standar lingkungan tiap negara mutlak diperlukan.","sentence_template":"グローバルに展開する企業[blank]、各国の法規制や環境基準への対応が不可欠だ。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, 'グローバルに展開する企業ともなると menekankan kompleksitas standar global.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 一流の通訳者___、言葉の置き換えだけでなく話者の意図や文化的背景まで的確に伝える。', '{"options":["に至っては","ずにはおかない","極まりなく","ともなれば"],"translation":"Kalau sudah juru bahasa kelas satu, bukan hanya menerjemahkan kata tetapi juga menyampaikan maksud pembicara dan latar budaya secara tepat.","sentence_template":"一流の通訳者[blank]、言葉の置き換えだけでなく話者の意図や文化的背景まで的確に伝える。"}'::jsonb, '{"selected":"ともなれば"}'::jsonb, '一流の通訳者ともなれば menggambarkan standar keunggulan profesional puncak.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan bisnis berikut. Apa tantangan yang dihadapi saat skala perusahaan membesar?', '{"audio_text":"海外拠点が十カ国以上ともなると、時差や商習慣の違いを踏まえた柔軟なガバナンスが問われる。","options":[{"id":"opt_1","text":"Semua cabang luar negeri harus menggunakan satu zona waktu yang sama"},{"id":"opt_2","text":"Diperlukan tata kelola fleksibel yang memperhitungkan perbedaan zona waktu dan kebiasaan bisnis"},{"id":"opt_3","text":"Perusahaan sebaiknya menutup seluruh cabang di luar negeri"},{"id":"opt_4","text":"Tidak ada perbedaan kebiasaan bisnis antarnegara"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '柔軟なガバナンスが問われる berarti ''tata kelola yang fleksibel menjadi ujian/tuntutan utama''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar kritikus arsitektur berikut. Apa keistimewaan gedung pencakar langit modern?', '{"audio_text":"高さ三百メートルを超える超高層ビルともなれば、耐震設計と風圧対策に最先端の工学技術が結集される。","options":[{"id":"opt_1","text":"Gedung tersebut dibangun tanpa memperhatikan ketahanan gempa"},{"id":"opt_2","text":"Biaya pembangunannya sama dengan rumah tinggal biasa"},{"id":"opt_3","text":"Teknologi rekayasa termutakhir dikerahkan untuk desain tahan gempa dan penahan tekanan angin"},{"id":"opt_4","text":"Gedung tersebut hanya membutuhkan waktu satu bulan untuk selesai"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '最先端の工学技術が結集される berarti ''teknologi rekayasa paling mutakhir dihimpun/dikerahkan''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah menjadi perwakilan negara, setiap sikap menjadi sorotan."', '{"tokens":["振る舞いが","代表","を余儀なく","なりに","一つ一つの","ともなると","注目される","国の"],"target_translation":"Jika sudah menjadi perwakilan negara, setiap sikap menjadi sorotan.","romaji":"Kuni no daihyou to mo naru to hitotsu hitotsu no furumai ga chuumoku sareru."}'::jsonb, '["国の","代表","ともなると","一つ一つの","振る舞いが","注目される"]'::jsonb, '振る舞いが注目される berarti ''setiap tindak-tanduk menjadi pusat perhatian''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah pada tahap perjanjian internasional, satu kata pun ditelaah dengan saksama."', '{"display_text":"国際条約の締結ともなれば、一字一句まで慎重に精査される。","romaji":"Kokusai jouyaku no teiketsu to mo nareba, ichiji ikku made shinchou ni seisa sareru.","phonetic_breakdown":["ko-ku-sai","jou-ya-ku","no","tei-ke-tsu","to","mo","na-re-ba","i-chi-ji","i-kku","ma-de","shin-chou","ni","sei-sa","sa-re-ru"]}'::jsonb, '{"expected_transcript":"国際条約の締結ともなれば、一字一句まで慎重に精査される。"}'::jsonb, '一字一句まで精査される berarti ''diteliti secara saksama hingga setiap huruf dan kata''.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index) VALUES (v_level_id, 'Tanpa Memandang Kondisi (～いかんによらず)', 'Kuasai bahasa regulasi, prinsip keadilan hukum, kepatuhan korporasi (compliance), dan klausul resmi tanpa pengecualian.', 'curriculum', 9) RETURNING id INTO v_unit_id;
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kosakata Regulasi & Kepatuhan', 'Kosakata Regulasi', 'n1-u9-kosakata', 'scales', 15, 1) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah hukum yang tepat: 利用___に違反した場合、アカウントが停止されることがある。', '{"options":["規約","要約","予約","節約"],"translation":"Apabila melanggar ketentuan penggunaan, akun dapat ditangguhkan.","sentence_template":"利用[blank]に違反した場合、アカウントが停止されることがある。"}'::jsonb, '{"selected":"規約"}'::jsonb, '利用規約 (riyou kiyaku) adalah padanan resmi untuk ''Terms of Service / Ketentuan Penggunaan''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kepatuhan korporasi berikut: 重大な規定違反に対しては、厳正な___が科される。', '{"options":["処分","成分","配分","気分"],"translation":"Terhadap pelanggaran aturan berat, sanksi yang tegas akan dijatuhkan.","sentence_template":"重大な規定違反に対しては、厳正な[blank]が科される。"}'::jsonb, '{"selected":"処分"}'::jsonb, '厳正な処分が科される berarti ''dijatuhi sanksi/tindakan disipliner yang tegas dan adil''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk prinsip seleksi: 採用試験は、すべての応募者に対して___に行われなければならない。', '{"options":["不均","恣意","偏狭","公平"],"translation":"Ujian rekrutmen harus dilaksanakan secara adil terhadap seluruh pelamar.","sentence_template":"採用試験は、すべての応募者に対して[blank]に行われなければならない。"}'::jsonb, '{"selected":"公平"}'::jsonb, '公平に (kouhei ni) berarti ''secara adil dan tidak memihak''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman kepatuhan perusahaan berikut. Kewajiban apa yang berlaku bagi seluruh pegawai?', '{"audio_text":"全社員は、業務上知り得た機密情報を第三者に漏洩しない守秘義務を負う。","options":[{"id":"opt_1","text":"Mempublikasikan seluruh data internal di media sosial"},{"id":"opt_2","text":"Menjaga kerahasiaan informasi sensitif pekerjaan agar tidak bocor ke pihak ketiga"},{"id":"opt_3","text":"Hanya manajer senior yang terikat kewajiban kerahasiaan"},{"id":"opt_4","text":"Menyimpan dokumen rahasia di komputer pribadi di rumah"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '守秘義務を負う (shuhi gimu wo ou) berarti ''memikul kewajiban menjaga kerahasiaan (NDA)''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan ketentuan seleksi beasiswa berikut. Bagaimana proses penilaian dilakukan?', '{"audio_text":"提出された書類は、外部の有識者を含む審査委員会によって厳格に評価されます。","options":[{"id":"opt_1","text":"Dipilih secara acak melalui undian terbuka"},{"id":"opt_2","text":"Dinilai hanya berdasarkan urutan waktu pengiriman"},{"id":"opt_3","text":"Dinilai secara ketat oleh komite penyeleksi yang mencakup pakar eksternal"},{"id":"opt_4","text":"Semua pendaftar otomatis dinyatakan lulus tanpa seleksi"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '審査委員会によって厳格に評価されます berarti ''dievaluasi secara ketat oleh komite seleksi''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Semua orang setara di hadapan hukum."', '{"display_text":"法の下において、すべての人は平等に扱われなければならない。","romaji":"Hou no moto ni oite, subete no hito wa byoudou ni atsukaware nakereba naranai.","phonetic_breakdown":["hou","no","mo-to","ni","o-i-te","su-be-te","no","hi-to","wa","byou-dou","ni","a-tsu-ka-wa-re","na-ke-re-ba","na-ra-nai"]}'::jsonb, '{"expected_transcript":"法の下において、すべての人は平等に扱われなければならない。"}'::jsonb, '法の下の平等 adalah prinsip fundamental hukum modern dalam bahasa Jepang formal.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Pola ～いかんによらず & Variannya', 'Pola いかんによらず', 'n1-u9-pola-utama', 'sparkle', 20, 2) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi klausul peraturan berikut: 理由の___、期限を過ぎた申請書は一切受理いたしません。', '{"options":["いかんによらず","いかんによって","いかんで","極まりなく"],"translation":"Tanpa memandang apa pun alasannya, formulir permohonan yang melewati tenggat sama sekali tidak akan diterima.","sentence_template":"理由の[blank]、期限を過ぎた申請書は一切受理いたしません。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, 'Kata benda (+ の) + いかんによらず / いかんにかかわらず berarti ''tanpa memandang bagaimana pun kondisi X''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang menyatakan ketergantungan pada kondisi (bukan mengabaikan): 調査結果の___、計画を中止せざるを得なくなる可能性がある。', '{"options":["いかんにかかわらず","いかんによっては","いかんによらず","いかんを問わず"],"translation":"Bergantung pada bagaimana hasil penyelidikannya, ada kemungkinan proyek terpaksa dibatalkan.","sentence_template":"調査結果の[blank]、計画を中止せざるを得なくなる可能性がある。"}'::jsonb, '{"selected":"いかんによっては"}'::jsonb, 'Perhatikan bedanya: ～いかんによらず (tanpa memandang) vs ～いかんによっては / ～いかんで (bergantung pada).', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat formal berikut: 当社は、国籍や性別の___、公正な評価制度を採用している。', '{"options":["いかんで","ともなると","に至って","いかんにかかわらず"],"translation":"Perusahaan kami menerapkan sistem evaluasi yang adil tanpa memandang kewarganegaraan maupun jenis kelamin.","sentence_template":"当社は、国籍や性別の[blank]、公正な評価制度を採用している。"}'::jsonb, '{"selected":"いかんにかかわらず"}'::jsonb, '～いかんにかかわらず bersinonim erat dengan ～いかんによらず dalam dokumen kebijakan SDM.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang hasilnya, kita harus menerima keputusan juri."', '{"tokens":["いかんに","判定に","なりに","結果の","審査員の","よらず","とはいえ","従う"],"target_translation":"Tanpa memandang hasilnya, kita harus menerima keputusan juri.","romaji":"Kekka no ikan ni yorazu shinsain no hantei ni shitagau."}'::jsonb, '["結果の","いかんに","よらず","審査員の","判定に","従う"]'::jsonb, '結果のいかんによらず berarti ''apa pun hasilnya / tanpa memandang hasilnya''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang status jabatan, pelanggaran hukum akan ditindak tegas."', '{"tokens":["不正行為は","処罰される","をもって","よらず","厳しく","いかんに","役職の","極まりない"],"target_translation":"Tanpa memandang status jabatan, pelanggaran hukum akan ditindak tegas.","romaji":"Yakushoku no ikan ni yorazu fusei koui wa kibishiku shobatsu sareru."}'::jsonb, '["役職の","いかんに","よらず","不正行為は","厳しく","処罰される"]'::jsonb, '役職のいかんによらず menegaskan prinsip kesetaraan aturan tanpa pengecualian pangkat.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang usia atau pengalaman, siapa pun dapat melamar."', '{"display_text":"年齢や経歴のいかんによらず、どなたでもご応募いただけます。","romaji":"Nenrei ya keireki no ikan ni yorazu, donata demo go-oubo itadakemasu.","phonetic_breakdown":["nen-rei","ya","kei-re-ki","no","i-kan","ni","yo-ra-zu","do-na-ta","de-mo","go-ou-bo","i-ta-da-ke-ma-su"]}'::jsonb, '{"expected_transcript":"年齢や経歴のいかんによらず、どなたでもご応募いただけます。"}'::jsonb, 'Ungkapan pengumuman lowongan atau kompetisi yang sangat resmi dan inklusif.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Klausul Hukum & Kepatuhan Publik', 'Dengar & Baca U9', 'n1-u9-dengar-baca', 'play-circle', 20, 3) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan ketentuan tiket acara berikut. Bagaimana kebijakan pengembalian dana?', '{"audio_text":"ご購入後のチケットは、お客様のご都合のいかんによらず、払い戻しには応じかねます。","options":[{"id":"opt_1","text":"Tiket dapat dikembalikan penuh kapan saja tanpa syarat"},{"id":"opt_2","text":"Pengembalian dana tidak dapat dilayani apa pun alasan dari pihak pembeli"},{"id":"opt_3","text":"Pembeli mendapat potongan lima puluh persen untuk acara berikutnya"},{"id":"opt_4","text":"Tiket hanya dapat ditukar di loket stasiun"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, 'ご都合のいかんによらず、払い戻しには応じかねます berarti ''apa pun alasan pelanggan, pengembalian uang tidak dapat dilayani''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan aturan keselamatan kerja berikut. Apa yang diwajibkan di area pabrik?', '{"audio_text":"滞在時間の長短のいかんにかかわらず、工場内では必ず保護帽を着用してください。","options":[{"id":"opt_1","text":"Helm pengaman hanya wajib jika berada di pabrik lebih dari satu jam"},{"id":"opt_2","text":"Tamu kunjungan singkat dibebaskan dari kewajiban memakai helm"},{"id":"opt_3","text":"Helm pengaman wajib dipakai di dalam pabrik tanpa memandang lama atau singkatnya kunjungan"},{"id":"opt_4","text":"Helm pengaman hanya disediakan untuk operator mesin berat"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '滞在時間の長短のいかんにかかわらず berarti ''tidak peduli sebentar atau lama berada di lokasi''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan dewan etik berikut. Bagaimana sikap mereka terhadap pelanggaran aturan?', '{"audio_text":"故意か過失かのいかんを問わず、重大な情報管理義務違反には厳正に対処する方針である。","options":[{"id":"opt_1","text":"Pelanggaran berat tetap ditindak tegas baik dilakukan sengaja maupun karena kelalaian"},{"id":"opt_2","text":"Pelanggaran karena kelalaian tidak akan dikenai sanksi apa pun"},{"id":"opt_3","text":"Hanya pelanggaran yang merugikan finansial yang diperiksa"},{"id":"opt_4","text":"Dewan etik menyerahkan sanksi sepenuhnya kepada masing-masing divisi"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '故意か過失かのいかんを問わず berarti ''tanpa memandang apakah disengaja (故意) atau lalai (過失)''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi ketentuan layanan berikut: 被害額の大小の___、不正アクセスが確認された場合は速やかに警察へ通報する。', '{"options":["いかんによらず","いかんによっては","いかんで","に至っては"],"translation":"Tanpa memandang besar kecilnya nilai kerugian, apabila akses ilegal terkonfirmasi, segera laporkan ke polisi.","sentence_template":"被害額の大小の[blank]、不正アクセスが確認された場合は速やかに警察へ通報する。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, '大小のいかんによらず menegaskan tidak ada ambang batas pengecualian dalam pelaporan insiden keamanan.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat: 今回の交渉の成否___、当社の来期の方針が大きく左右される。', '{"options":["いかんによらず","いかんで","いかんにかかわらず","いかんを問わず"],"translation":"Bergantung pada berhasil tidaknya negosiasi kali ini, arah kebijakan perusahaan periode depan akan sangat terpengaruh.","sentence_template":"今回の交渉の成否[blank]、当社の来期の方針が大きく左右される。"}'::jsonb, '{"selected":"いかんで"}'::jsonb, '成否いかんで (bergantung pada berhasil atau gagalnya) karena kalimat menyatakan pengaruh langsung.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi klausul berikut: 天候の___、本大会は屋内会場にて予定通り開催いたします。', '{"options":["を余儀なく","なりに","いかんによらず","とはいえ"],"translation":"Tanpa memandang kondisi cuaca, turnamen ini akan diselenggarakan sesuai jadwal di gedung tertutup.","sentence_template":"天候の[blank]、本大会は屋内会場にて予定通り開催いたします。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, '天候のいかんによらず (bagaimanapun kondisi cuacanya) karena acara berlangsung di dalam ruangan.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Bicara & Rakit Prinsip Kepatuhan', 'Bicara & Rakit U9', 'n1-u9-bicara-rakit', 'microphone', 20, 4) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang latar belakang, semua anggota memiliki hak yang sama."', '{"display_text":"出身や経歴のいかんによらず、全会員は平等の権利を有する。","romaji":"Shusshin ya keireki no ikan ni yorazu, zenkaiin wa byoudou no kenri wo yuusuru.","phonetic_breakdown":["shu-sshin","ya","kei-re-ki","no","i-kan","ni","yo-ra-zu","zen-kai-in","wa","byou-dou","no","ken-ri","wo","yuu-su-ru"]}'::jsonb, '{"expected_transcript":"出身や経歴のいかんによらず、全会員は平等の権利を有する。"}'::jsonb, '権利を有する (memiliki hak) adalah istilah baku dalam anggaran dasar dan peraturan organisasi.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang alasan, kekerasan tidak pernah dapat dibenarkan."', '{"display_text":"いかなる理由のいかんによらず、暴力は決して容認されない。","romaji":"Ikanaru riyuu no ikan ni yorazu, bouryoku wa kesshite younin sarenai.","phonetic_breakdown":["i-ka-na-ru","ri-yuu","no","i-kan","ni","yo-ra-zu","bou-ryo-ku","wa","ke-sshi-te","you-nin","sa-re-nai"]}'::jsonb, '{"expected_transcript":"いかなる理由のいかんによらず、暴力は決して容認されない。"}'::jsonb, '容認されない (younin sarenai) berarti ''tidak dapat dibenarkan/ditoleransi''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang skala perusahaan, perlindungan data adalah kewajiban bersama."', '{"display_text":"企業規模のいかんにかかわらず、個人情報保護の徹底が求められる。","romaji":"Kigyou kibo no ikan ni kakawarazu, kojin jouhou hogo no tettei ga motomerareru.","phonetic_breakdown":["ki-gyou","ki-bo","no","i-kan","ni","ka-ka-wa-ra-zu","ko-jin","jou-hou","ho-go","no","te-ttei","ga","mo-to-me-ra-re-ru"]}'::jsonb, '{"expected_transcript":"企業規模のいかんにかかわらず、個人情報保護の徹底が求められる。"}'::jsonb, '個人情報保護の徹底 (penerapan ketat perlindungan data pribadi).', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang hasil ujian, usahamu selama ini tidak sia-sia."', '{"tokens":["努力は","よらず","をもって","これまでの","無駄にならない","合否の","いかんに","極まりない"],"target_translation":"Tanpa memandang hasil ujian, usahamu selama ini tidak sia-sia.","romaji":"Gouhi no ikan ni yorazu kore made no doryoku wa muda ni naranai."}'::jsonb, '["合否の","いかんに","よらず","これまでの","努力は","無駄にならない"]'::jsonb, '合否のいかんによらず berarti ''tanpa memandang lulus atau tidak lulus''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang posisi, semua karyawan wajib mematuhi kode etik."', '{"tokens":["義務がある","とはいえ","なりに","よらず","いかんに","立場の","遵守する","行動規範を"],"target_translation":"Tanpa memandang posisi, semua karyawan wajib mematuhi kode etik.","romaji":"Tachiba no ikan ni yorazu koudou kihan wo junshu suru gimu ga aru."}'::jsonb, '["立場の","いかんに","よらず","行動規範を","遵守する","義務がある"]'::jsonb, '行動規範を遵守する (mematuhi kode etik perilaku).', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Bergantung pada isi jawaban pihak lawan, kami akan meninjau langkah berikutnya."', '{"tokens":["次の","いかんでは","対応を","に至って","回答","ながら","先方の","検討する"],"target_translation":"Bergantung pada isi jawaban pihak lawan, kami akan meninjau langkah berikutnya.","romaji":"Senpou no kaitou ikan de wa tsugi no taiou wo kentou suru."}'::jsonb, '["先方の","回答","いかんでは","次の","対応を","検討する"]'::jsonb, '回答いかんでは (bergantung pada bagaimana jawaban pihak lawan).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Tes Akhir Unit 9', 'Tes Akhir U9', 'n1-u9-tes-akhir', 'trophy', 25, 5) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk klausul resmi: 事由の___、許可なく館内で撮影を行うことは固く禁じられている。', '{"options":["とはいえ","ともなると","いかんによらず","いかんで"],"translation":"Tanpa memandang apa pun alasannya, mengambil gambar di dalam gedung tanpa izin dilarang keras.","sentence_template":"事由の[blank]、許可なく館内で撮影を行うことは固く禁じられている。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, '事由のいかんによらず adalah formulasi hukum yang sangat tepat untuk larangan tanpa pengecualian.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 採択の可否の___、提出された応募書類は返却いたしません。', '{"options":["に足らず","いかんによっては","をもって","いかんにかかわらず"],"translation":"Tanpa memandang diterima atau ditolaknya lamaran, berkas yang telah diserahkan tidak akan dikembalikan.","sentence_template":"採択の可否の[blank]、提出された応募書類は返却いたしません。"}'::jsonb, '{"selected":"いかんにかかわらず"}'::jsonb, '採択の可否のいかんにかかわらず lazim tercantum pada panduan pendaftaran hibah atau rekrutmen.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pernyataan kepala rumah sakit berikut. Apa prinsip pelayanan medis yang dipegang?', '{"audio_text":"患者の社会的地位や経済状況のいかんによらず、当院はすべての人に最善の医療を提供する。","options":[{"id":"opt_1","text":"Memberikan layanan medis terbaik kepada semua orang tanpa memandang status sosial atau ekonomi"},{"id":"opt_2","text":"Hanya menerima pasien dengan asuransi swasta khusus"},{"id":"opt_3","text":"Memprioritaskan pasien berdasarkan jabatan publik mereka"},{"id":"opt_4","text":"Menutup layanan gawat darurat pada akhir pekan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '社会的地位や経済状況のいかんによらず menegaskan prinsip kesetaraan layanan medis.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar panitia lelang berikut. Apa syarat mutlak pengajuan penawaran?', '{"audio_text":"企業の規模や実績のいかんを問わず、透明な手続きのもとで最も優れた提案を採用いたします。","options":[{"id":"opt_1","text":"Hanya perusahaan berusia di atas lima puluh tahun yang boleh ikut"},{"id":"opt_2","text":"Proposal terbaik akan dipilih secara transparan tanpa memandang skala atau rekam jejak perusahaan"},{"id":"opt_3","text":"Pemenang lelang sudah ditentukan sebelum proposal dibuka"},{"id":"opt_4","text":"Perusahaan kecil dilarang mengajukan penawaran"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '企業の規模や実績のいかんを問わず berarti ''tanpa memandang besar kecilnya perusahaan atau rekam jejaknya''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang status keanggotaan, biaya masuk dibebaskan hari ini."', '{"tokens":["いかんに","よらず","本日は","入場無料だ","会員資格の","なりに","有無の","極まりない"],"target_translation":"Tanpa memandang status keanggotaan, biaya masuk dibebaskan hari ini.","romaji":"Kaiin shikaku no umu no ikan ni yorazu honjitsu wa nyuujou muryou da."}'::jsonb, '["会員資格の","有無の","いかんに","よらず","本日は","入場無料だ"]'::jsonb, '有無のいかんによらず berarti ''tanpa memandang ada atau tidak adanya''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang perbedaan pendapat, kita harus menghormati aturan rapat."', '{"display_text":"見解の相違のいかんによらず、会議のルールは遵守すべきである。","romaji":"Kenkai no soui no ikan ni yorazu, kaigi no ruuru wa junshu subeki de aru.","phonetic_breakdown":["ken-kai","no","sou-i","no","i-kan","ni","yo-ra-zu","kai-gi","no","ruu-ru","wa","jun-shu","su-be-ki","de","a-ru"]}'::jsonb, '{"expected_transcript":"見解の相違のいかんによらず、会議のルールは遵守すべきである。"}'::jsonb, '見解の相違 (perbedaan pandangan) dan 遵守すべき (wajib dipatuhi).', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index) VALUES (v_level_id, 'Layak Untuk (～に足る)', 'Evaluasi kualitas, kredibilitas, dan kelayakan gagasan secara akademis maupun eksekutif, ditutup dengan sintesis kesiapan JLPT N1.', 'curriculum', 10) RETURNING id INTO v_unit_id;
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Kosakata Penilaian & Kredibilitas', 'Kosakata Penilaian', 'n1-u10-kosakata', 'graduation-cap', 15, 1) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah akademis yang tepat: 主張を裏付ける客観的な___が不足しているため、再調査が必要だ。', '{"options":["噂話","根拠","偏見","空想"],"translation":"Karena dasar/bukti objektif yang mendukung argumen masih kurang, penyelidikan ulang diperlukan.","sentence_template":"主張を裏付ける客観的な[blank]が不足しているため、再調査が必要だ。"}'::jsonb, '{"selected":"根拠"}'::jsonb, '客観的な根拠 (kyakkanteki na konkyo) berarti ''dasar/bukti yang objektif''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi profesional berikut: 長年の確かな___により、その企業は業界内外から厚い信頼を得ている。', '{"options":["失敗","遅延","実績","誇張"],"translation":"Berkat rekam jejak nyata selama bertahun-tahun, perusahaan itu memperoleh kepercayaan mendalam dari dalam dan luar industri.","sentence_template":"長年の確かな[blank]により、その企業は業界内外から厚い信頼を得ている。"}'::jsonb, '{"selected":"実績"}'::jsonb, '確かな実績 (tashika na jisseki) berarti ''rekam jejak/pencapaian nyata yang terbukti''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata kerja formal untuk menguji kebenaran data: 提出された仮説の妥当性を、複数の実験によって徹底的に___した。', '{"options":["憶測","無視","検証","放置"],"translation":"Keabsahan hipotesis yang diajukan telah diverifikasi secara menyeluruh melalui beberapa eksperimen.","sentence_template":"提出された仮説の妥当性を、複数の実験によって徹底的に[blank]した。"}'::jsonb, '{"selected":"検証"}'::jsonb, '妥当性を検証する (datousei wo kenshou suru) berarti ''memverifikasi keabsahan/validitas''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan komentar juri penghargaan berikut. Mengapa penelitian itu dipuji tinggi?', '{"audio_text":"この研究は新規性と社会的意義の両面において極めて価値が高く、国際的な評価に値する。","options":[{"id":"opt_1","text":"Penelitian itu tidak memiliki kebaruan sama sekali"},{"id":"opt_2","text":"Penelitian itu bernilai sangat tinggi dari sisi kebaruan dan makna sosialnya"},{"id":"opt_3","text":"Penelitian itu ditolak karena kurang relevan bagi masyarakat"},{"id":"opt_4","text":"Penelitian itu belum selesai diuji di laboratorium"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '新規性と社会的意義 (kebaruan dan signifikansi sosial) menjadikannya bernilai sangat tinggi.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pendapat rekan kerja berikut. Bagaimana penilaiannya terhadap pemimpin baru tersebut?', '{"audio_text":"誠実な人柄と的確な判断力を兼ね備えた彼女は、誰からも敬意を集める人物だ。","options":[{"id":"opt_1","text":"Ia sosok yang dihormati semua orang berkat kepribadian tulus dan penilaian yang tepat"},{"id":"opt_2","text":"Ia sering ragu-ragu dalam mengambil keputusan penting"},{"id":"opt_3","text":"Ia jarang berkomunikasi dengan anggota timnya"},{"id":"opt_4","text":"Ia baru saja mengundurkan diri dari jabatannya"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '誠実な人柄と的確な判断力を兼ね備えた berarti ''memadukan karakter tulus dan daya nilai yang jitu''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Usulan itu memiliki dasar yang kuat dan layak dipertimbangkan."', '{"display_text":"その提案には明確な根拠があり、検討する価値が十分にある。","romaji":"Sono teian ni wa meikaku na konkyo ga ari, kentou suru kachi ga juubun ni aru.","phonetic_breakdown":["so-no","tei-an","ni","wa","mei-ka-ku","na","kon-kyo","ga","a-ri","ken-tou","su-ru","ka-chi","ga","juu-bun","ni","a-ru"]}'::jsonb, '{"expected_transcript":"その提案には明確な根拠があり、検討する価値が十分にある。"}'::jsonb, '明確な根拠 (dasar yang jelas) dan 検討する価値 (nilai kelayakan untuk dikaji).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Pola ～に足る & ～に足りない', 'Pola ～に足る', 'n1-u10-pola-utama', 'sparkle', 20, 2) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi berikut: 彼は長年の誠実な仕事ぶりから、十分に信頼___人物である。', '{"options":["を余儀なく","極まりない","に至る","に足る"],"translation":"Dari rekam kerja tulusnya selama bertahun-tahun, ia adalah sosok yang sangat layak dipercaya.","sentence_template":"彼は長年の誠実な仕事ぶりから、十分に信頼[blank]人物である。"}'::jsonb, '{"selected":"に足る"}'::jsonb, 'Kata benda / kata kerja bentuk kamus + に足る berarti ''layak/cukup bernilai untuk...''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk negatif yang tepat untuk menyatakan sesuatu yang sepele: それは些細なミスであり、わざわざ問題視する___。', '{"options":["に足る","に足りない","ずにはおかない","に至らない"],"translation":"Itu hanyalah kesalahan sepele dan tidak layak untuk dipermasalahkan.","sentence_template":"それは些細なミスであり、わざわざ問題視する[blank]。"}'::jsonb, '{"selected":"に足りない"}'::jsonb, '～に足りない (atau ～に足らない) berarti ''tidak layak / tidak sepadan untuk (dikhawatirkan/dipermasalahkan)''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat ilmiah berikut: 今回得られたデータは、学術的な議論___高い精度を備えている。', '{"options":["に足る","なりに","をもって","とはいえ"],"translation":"Data yang diperoleh kali ini memiliki presisi tinggi yang layak untuk diperdebatkan secara akademis.","sentence_template":"今回得られたデータは、学術的な議論[blank]高い精度を備えている。"}'::jsonb, '{"selected":"に足る"}'::jsonb, '議論に足る berarti ''layak dijadikan bahan diskusi/kajian''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Itu adalah kekhawatiran kecil yang tidak layak dirisaukan."', '{"tokens":["噂は","気にする","足りない","極まりない","をもって","そんな","に","小さな"],"target_translation":"Itu adalah kekhawatiran kecil yang tidak layak dirisaukan.","romaji":"Sonna chiisana uwasa wa ki ni suru ni tarinai."}'::jsonb, '["そんな","小さな","噂は","気にする","に","足りない"]'::jsonb, '気にするに足りない (atau 気にするに足らない) berarti ''tidak pantas untuk dipusingkan''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Pencapaiannya layak menerima penghormatan tertinggi."', '{"tokens":["に足る","深い","なりに","ものだ","彼の","とはいえ","敬意","功績は"],"target_translation":"Pencapaiannya layak menerima penghormatan tertinggi.","romaji":"Kare no kouseki wa fukai keii ni taru mono da."}'::jsonb, '["彼の","功績は","深い","敬意","に足る","ものだ"]'::jsonb, '敬意に足る berarti ''layak mendapatkan rasa hormat''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Ini adalah temuan luar biasa yang layak mendapat perhatian dunia."', '{"display_text":"これは世界の注目に足る画期的な成果である。","romaji":"Kore wa sekai no chuumoku ni taru kakkiteki na seika de aru.","phonetic_breakdown":["ko-re","wa","se-kai","no","chuu-mo-ku","ni","ta-ru","ka-kki-te-ki","na","sei-ka","de","a-ru"]}'::jsonb, '{"expected_transcript":"これは世界の注目に足る画期的な成果である。"}'::jsonb, '注目に足る (layak diperhatikan) dan 画期的な成果 (pencapaian terobosan).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Evaluasi Kualitas & Reputasi', 'Dengar & Baca U10', 'n1-u10-dengar-baca', 'play-circle', 20, 3) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan tanggapan direktur berikut. Bagaimana ia menilai rumor di media sosial?', '{"audio_text":"出所不明の憶測に基づく批判など、いちいち反論するに足りないものだ。","options":[{"id":"opt_1","text":"Ia menilai kritik berdasar spekulasi tak jelas itu tidak layak dibantah satu per satu"},{"id":"opt_2","text":"Ia akan segera menggelar konferensi pers untuk membahas setiap komentar"},{"id":"opt_3","text":"Ia membenarkan seluruh isi rumor yang beredar"},{"id":"opt_4","text":"Ia meminta semua karyawan berhenti menggunakan internet"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '反論するに足りない berarti ''tidak layak untuk dibantah''.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan penilaian dosen pembimbing berikut. Apa kualitas makalah mahasiswa tersebut?', '{"audio_text":"先行研究を丹念に検証したこの論文は、学会での発表に足る高い完成度を誇っている。","options":[{"id":"opt_1","text":"Makalah itu belum layak dipresentasikan karena kurang referensi"},{"id":"opt_2","text":"Makalah itu memiliki tingkat kematangan tinggi yang layak dipresentasikan di konferensi ilmiah"},{"id":"opt_3","text":"Makalah itu harus ditulis ulang dari awal bulan depan"},{"id":"opt_4","text":"Makalah itu terlalu singkat untuk dinilai"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '発表に足る高い完成度 berarti ''tingkat kesempurnaan tinggi yang layak dipresentasikan''.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan ulasan komite seleksi mitra bisnis. Apa syarat utama kandidat perusahaan?', '{"audio_text":"長期的な共同開発を任せる以上、技術力と財務基盤の双方で信頼に足る企業を選定したい。","options":[{"id":"opt_1","text":"Memilih perusahaan dengan biaya termurah tanpa melihat stabilitas keuangan"},{"id":"opt_2","text":"Hanya memilih perusahaan baru yang belum memiliki laporan keuangan"},{"id":"opt_3","text":"Memilih perusahaan yang layak dipercaya baik dari segi teknologi maupun fondasi keuangan"},{"id":"opt_4","text":"Menunda pemilihan mitra selama lima tahun"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '技術力と財務基盤の双方で信頼に足る企業 berarti ''perusahaan yang layak dipercaya di kedua aspek teknologi dan keuangan''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: わずかな誤差は統計上、取る___小さなものに過ぎない。', '{"options":["に足りない","に足る","に至った","を余儀なくされた"],"translation":"Selisih kecil tersebut secara statistik hanyalah hal remeh yang tidak berarti.","sentence_template":"わずかな誤差は統計上、取る[blank]小さなものに過ぎない。"}'::jsonb, '{"selected":"に足りない"}'::jsonb, '取るに足りない (toru ni tarinai) adalah ungkapan baku N1 untuk ''sangat remeh / tidak berarti''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼の提案は斬新であり、経営会議で真剣に検討する___。', '{"options":["なりに","に足る","とはいえ","いかんによらず"],"translation":"Usulannya segar dan layak dikaji secara serius dalam rapat manajemen.","sentence_template":"彼の提案は斬新であり、経営会議で真剣に検討する[blank]。"}'::jsonb, '{"selected":"に足る"}'::jsonb, '検討するに足る berarti ''layak untuk dipertimbangkan/dikaji''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi sejarah berikut: この出来事は、現代社会の転換点として特筆する___重要な意義を持つ。', '{"options":["ともなると","に足りない","極まりない","に足る"],"translation":"Peristiwa ini memiliki makna penting yang layak dicatat secara khusus sebagai titik balik masyarakat modern.","sentence_template":"この出来事は、現代社会の転換点として特筆する[blank]重要な意義を持つ。"}'::jsonb, '{"selected":"に足る"}'::jsonb, '特筆するに足る berarti ''layak dicatat secara istimewa (noteworthy)''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Bicara & Rakit Evaluasi N1', 'Bicara & Rakit U10', 'n1-u10-bicara-rakit', 'microphone', 20, 4) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Rencana bisnis ini memiliki prospek yang layak untuk diinvestasikan."', '{"display_text":"この事業計画は、長期的な投資に足る将来性を備えている。","romaji":"Kono jigyou keikaku wa, choukiteki na toushi ni taru shouraisei wo sonaete iru.","phonetic_breakdown":["ko-no","ji-gyou","kei-ka-ku","wa","chou-ki-te-ki","na","tou-shi","ni","ta-ru","shou-rai-sei","wo","so-na-e-te","i-ru"]}'::jsonb, '{"expected_transcript":"この事業計画は、長期的な投資に足る将来性を備えている。"}'::jsonb, '投資に足る将来性 (prospek masa depan yang layak menerima investasi).', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Perbedaan sekecil itu adalah hal remeh yang tidak perlu dikhawatirkan."', '{"display_text":"その程度の違いは、恐れるに足りない些細な問題だ。","romaji":"Sono teido no chigai wa, osoreru ni tarinai sasai na mondai da.","phonetic_breakdown":["so-no","tei-do","no","chi-gai","wa","o-so-re-ru","ni","ta-ri-nai","sa-sai","na","mon-dai","da"]}'::jsonb, '{"expected_transcript":"その程度の違いは、恐れるに足りない些細な問題だ。"}'::jsonb, '恐れるに足りない (tidak layak ditakuti) dan 些細な問題 (masalah sepele).', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pengalamannya yang luas membuatnya layak memimpin proyek besar ini."', '{"display_text":"豊富な実績を持つ彼女こそ、この重責を任せるに足る人物だ。","romaji":"Houfu na jisseki wo motsu kanojo koso, kono juuseki wo makaseru ni taru jinbutsu da.","phonetic_breakdown":["hou-fu","na","ji-sse-ki","wo","mo-tsu","ka-no-jo","ko-so","ko-no","juu-se-ki","wo","ma-ka-se-ru","ni","ta-ru","jin-bu-tsu","da"]}'::jsonb, '{"expected_transcript":"豊富な実績を持つ彼女こそ、この重責を任せるに足る人物だ。"}'::jsonb, '重責を任せるに足る人物 berarti ''sosok yang layak diserahi tanggung jawab berat''.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Bukti tersebut masih kurang meyakinkan untuk dijadikan dasar keputusan."', '{"tokens":["足らない","とする","なりに","判断の","に","その証拠は","極まりない","根拠"],"target_translation":"Bukti tersebut masih kurang meyakinkan untuk dijadikan dasar keputusan.","romaji":"Sono shouko wa handan no konkyo to suru ni taranai."}'::jsonb, '["その証拠は","判断の","根拠","とする","に","足らない"]'::jsonb, '根拠とするに足らない berarti ''tidak cukup layak untuk dijadikan dasar penilaian''.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karya ini layak disebut sebagai mahakarya sastra modern."', '{"tokens":["傑作と","に足る","呼ぶ","とはいえ","をもって","本作は","現代文学の","作品だ"],"target_translation":"Karya ini layak disebut sebagai mahakarya sastra modern.","romaji":"Honsaku wa gendai bungaku no kessaku to yobu ni taru sakuhin da."}'::jsonb, '["本作は","現代文学の","傑作と","呼ぶ","に足る","作品だ"]'::jsonb, '傑作と呼ぶに足る作品 berarti ''karya yang layak disebut mahakarya''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Informasi yang tidak terverifikasi itu adalah hal remeh."', '{"tokens":["ながら","に至って","足りない","に","取る","裏付けの","情報は","ない"],"target_translation":"Informasi yang tidak terverifikasi itu adalah hal remeh.","romaji":"Urazuke no nai jouhou wa toru ni tarinai."}'::jsonb, '["裏付けの","ない","情報は","取る","に","足りない"]'::jsonb, '裏付けのない情報 (informasi tanpa bukti pendukung) dinilai 取るに足りない.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES (v_unit_id, 'Ujian Kesiapan JLPT N1', 'Ujian Kesiapan N1', 'n1-u10-tes-akhir', 'trophy', 25, 5) RETURNING id INTO v_lesson_id;
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Uji kesiapan N1 — pilih pola yang tepat: 多角的な検証を経たこの報告書は、国際会議での議論___高い信頼性を備えている。', '{"options":["に足りない","を余儀なくされた","に足る","極まりない"],"translation":"Laporan yang telah melalui verifikasi multidimensi ini memiliki kredibilitas tinggi yang layak untuk dibahas di konferensi internasional.","sentence_template":"多角的な検証を経たこの報告書は、国際会議での議論[blank]高い信頼性を備えている。"}'::jsonb, '{"selected":"に足る"}'::jsonb, '議論に足る高い信頼性 menegaskan kelayakan laporan untuk forum internasional.', 1);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Sintesis N1 — lengkapi kalimat berita berikut: 度重なる遅延が続き、ついに契約解除___、同社は抜本的な体制刷新を余儀なくされた。', '{"options":["いかんによらず","なりに","に至るに及んで","に至って"],"translation":"Setelah keterlambatan berulang hingga akhirnya berujung pada pembatalan kontrak, perusahaan itu terpaksa merombak sistemnya secara mendasar.","sentence_template":"度重なる遅延が続き、ついに契約解除[blank]、同社は抜本的な体制刷新を余儀なくされた。"}'::jsonb, '{"selected":"に至って"}'::jsonb, 'Menggabungkan pola Unit 1 (～に至って) dan Unit 2 (～を余儀なくされた) dalam satu kalimat berita N1 yang utuh.', 2);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pernyataan penutup konferensi berikut. Apa yang ditegaskan oleh ketua panitia?', '{"audio_text":"立場や専門分野のいかんによらず、本日の議論は今後の社会を動かすに足る貴重な提言を生み出した。","options":[{"id":"opt_1","text":"Diskusi hari ini tidak menghasilkan rekomendasi apa pun"},{"id":"opt_2","text":"Hanya peserta dari satu bidang ilmu yang diperbolehkan berbicara"},{"id":"opt_3","text":"Konferensi dibatalkan sebelum sesi penutupan dimulai"},{"id":"opt_4","text":"Tanpa memandang jabatan atau bidang, diskusi melahirkan rekomendasi berharga yang layak menggerakkan masyarakat"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, 'Sintesis pola Unit 9 (～いかんによらず) dan Unit 10 (～に足る) dalam pidato penutupan formal.', 3);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar editorial berikut. Apa kesimpulan penulis tentang proyek pembaruan kota?', '{"audio_text":"財政的な制約があるとはいえ、次世代に誇れる街づくりを目指す姿勢は市民の共感を呼ばずにはおかない。","options":[{"id":"opt_1","text":"Warga menolak seluruh rencana penataan kota karena terlalu mahal"},{"id":"opt_2","text":"Meski terkendala anggaran, upaya membangun kota yang membanggakan generasi mendatang pasti mengundang empati warga"},{"id":"opt_3","text":"Anggaran pemerintah daerah berlebih sehingga proyek bisa dipercepat"},{"id":"opt_4","text":"Proyek tersebut hanya berfokus pada pembangunan gedung perkantoran"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, 'Sintesis pola Unit 3 (～とはいえ) dan Unit 7 (～ずにはおかない) dalam wacana tajuk rencana N1.', 4);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dengan dedikasi tinggi, mereka telah membangun reputasi yang layak dipercaya."', '{"tokens":["に足る","対応により","実績を築いた","とはいえ","長年の","信頼","誠実な","極まりない"],"target_translation":"Dengan dedikasi tinggi, mereka telah membangun reputasi yang layak dipercaya.","romaji":"Naganen no seijitsu na taiou ni yori shinrai ni taru jisseki wo kizuita."}'::jsonb, '["長年の","誠実な","対応により","信頼","に足る","実績を築いた"]'::jsonb, '信頼に足る実績を築いた berarti ''telah membangun rekam jejak yang layak dipercaya''.', 5);
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan selesainya tahap ini, Anda telah mencapai tingkat penguasaan yang layak dibanggakan."', '{"display_text":"これまでの学びをもって、誇りに足る高度な日本語力を身につけたと言えよう。","romaji":"Kore made no manabi wo motte, hokori ni taru koudo na nihongoryoku wo mi ni tsuketa to ieyou.","phonetic_breakdown":["ko-re","ma-de","no","ma-na-bi","wo","mo-tte","ho-ko-ri","ni","ta-ru","kou-do","na","ni-hon-go-ryo-ku","wo","mi","ni","tsu-ke-ta","to","i-e-you"]}'::jsonb, '{"expected_transcript":"これまでの学びをもって、誇りに足る高度な日本語力を身につけたと言えよう。"}'::jsonb, 'Sintesis elegan ～をもって (Unit 4) dan 誇りに足る (Unit 10: layak dibanggakan) sebagai penutup kurikulum JLPT N1.', 6);
