-- Seed JLPT N1 Japanese curriculum: 10 units, 50 lessons, 300 exercises
-- Aligned 1-to-1 with grammar points GP-JA-N1-001 through GP-JA-N1-010
DO $$
DECLARE
    v_level_id uuid;
    v_unit_id uuid;
    v_lesson_id uuid;
    v_gp_id uuid;
BEGIN
    SELECT pl.id INTO v_level_id
    FROM proficiency_levels pl
    JOIN languages l ON l.id = pl.language_id
    WHERE l.code = 'ja' AND pl.code = 'N1'
    LIMIT 1;

    IF v_level_id IS NULL THEN
        RETURN;
    END IF;

    DELETE FROM units WHERE level_id = v_level_id AND unit_type = 'curriculum';

    -- Unit 1: GP-JA-N1-001 - Hingga Mencapai Titik Kritis (～に至って)
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N1-001' LIMIT 1;






    -- Unit 2: GP-JA-N1-002 - Terpaksa Oleh Keadaan Luar (～を余儀なくされる)
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N1-002' LIMIT 1;






    -- Unit 3: GP-JA-N1-003 - Meskipun Memang Demikian (～とはいえ)
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N1-003' LIMIT 1;






    -- Unit 4: GP-JA-N1-004 - Dengan Sarana Resmi / Batas Waktu (～をもって)
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N1-004' LIMIT 1;






    -- Unit 5: GP-JA-N1-005 - Tingkat Ekstrem Tanpa Tandingan (～極まりない)
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N1-005' LIMIT 1;






    -- Unit 6: GP-JA-N1-006 - Dengan Caranya Sendiri (～なりに)
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N1-006' LIMIT 1;






    -- Unit 7: GP-JA-N1-007 - Pasti Menimbulkan Efek (～ずにはおかない)
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N1-007' LIMIT 1;






    -- Unit 8: GP-JA-N1-008 - Jika Sudah Sampai Level (～ともなると)
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N1-008' LIMIT 1;






    -- Unit 9: GP-JA-N1-009 - Tanpa Memandang Kondisi (～いかんによらず)
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N1-009' LIMIT 1;






    -- Unit 10: GP-JA-N1-010 - Layak Untuk (～に足る)
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N1-010' LIMIT 1;






END $$;
